    };

    pub fn init(allocator: Allocator, options: Options) Backend {
        var backend: Backend = undefined;
        initInPlace(&backend, allocator, options);
        return backend;
    }

    pub fn initInPlace(self: *Backend, allocator: Allocator, options: Options) void {
        self.* = .{
            .allocator = allocator,
            .options = options,
            .root_generation = options.root_generation,
            .compaction_scheduler = compaction_scheduler_mod.Scheduler.init(options.compaction_scheduler),
            .background_executor = resolveBackgroundExecutor(options.background_executor),
            .storage_owner = null,
            .storage = options.storage,
        };
        self.options.unpublished_outputs = null;
    }

    pub fn initOutputCleanup(self: *Backend) !void {
        if (self.options.backend.read_only) return;
        const queue = try self.allocator.create(output_cleanup.Queue);
        queue.* = .{ .allocator = self.allocator, .manager = self.options.resource_manager };
        if (self.options.maintenance_waker) |waker| {
            queue.wake_context = waker.ptr;
            queue.wake_fn = waker.wake_fn;
        }
        self.options.unpublished_outputs = queue;
    }

    pub fn deinitOutputCleanup(self: *Backend) void {
        if (self.options.unpublished_outputs) |queue| {
            queue.deinit();
            self.allocator.destroy(queue);
        }
        self.options.unpublished_outputs = null;
    }

    fn outputCleanupDelayLocked(self: *Backend) ?u64 {
        const queue = self.options.unpublished_outputs orelse return null;
        if (queue.pending.load(.acquire) == 0) return null;
        return self.output_cleanup_retry_at_ns -| self.nowNs();
    }

    /// One bounded metadata handoff. No physical deletion under Backend.mu.
    /// Tickets are restored to the queue on OOM/admission failure without
    /// allocating, including when the originating request was cancelled.
    fn drainOutputCleanupSliceLocked(self: *Backend) !bool {
        const queue = self.options.unpublished_outputs orelse return false;
        const deadline = runtime_mod.workNowNs(self) +| 2 * std.time.ns_per_ms;
        var progressed = false;
        for (0..64) |_| {
            if (runtime_mod.workNowNs(self) >= deadline) break;
            const ticket = queue.pop() orelse break;
            errdefer {
                queue.append(ticket);
                self.output_cleanup_admission_failures +|= 1;
                self.output_cleanup_retry_at_ns = self.nowNs() +| @max(std.time.ns_per_ms, self.options.obsolete_delete_retry_ns);
            }
            var credit = try self.admitCompactionMetadataBytes(32 +| ticket.path.len);
            defer credit.release();
            try self.obsolete_paths.ensureUnusedCapacity(self.allocator, 1);
            if (!self.obsolete_paths.contains(ticket.path)) {
                const path = try self.allocator.dupe(u8, ticket.path);
                self.obsolete_paths.appendAssumeCapacity(.{ .path = path, .delete_after_ns = self.nowNs() });
                self.obsolete_manifest_dirty = true;
                credit.commit();
            }
            ticket.destroy();
            progressed = true;
        }
        if (progressed) {
            self.output_cleanup_retry_at_ns = 0;
            self.obsolete_reclaim_retry_at_ns = 0;
        }
        return progressed;
    }

    pub const QuiescedCheckpointPreparation = @import("lsm_backend/checkpoint_preparation.zig").Preparation(Backend);

    pub const QuiescedOutputCleanup = @import("lsm_backend/prepared_output_cleanup.zig").Consumer(Backend);

    fn drainOutputCleanupLocked(self: *Backend) !void {
        while (self.outputCleanupDelayLocked() != null) {
            _ = try self.drainOutputCleanupSliceLocked();
            self.retainReaderKind(.other);
            self.mu.unlock();
            const yielded = if (self.manifestCoordinationIo()) |io| io.sleep(.fromNanoseconds(1), .awake) else @as(anyerror!void, {});
            _ = runtime_mod.lockBackend(Backend, self);
            self.releaseReaderKind(.other);
            try yielded;
        }
    }

    pub fn open(allocator: Allocator, root_dir: []const u8, options: Options) !Backend {
        const normalized_options = normalizeOptionsForDurability(options);
        return try recovery_mod.open(Backend, allocator, root_dir, normalized_options.backend, normalized_options);
    }

    pub fn openInto(self: *Backend, allocator: Allocator, root_dir: []const u8, options: Options) !void {
        const normalized_options = normalizeOptionsForDurability(options);
        try recovery_mod.openInto(Backend, self, allocator, root_dir, normalized_options.backend, normalized_options);
    }

    pub fn close(self: *Backend) void {
        self.closing.store(true, .release);
        self.detachLocalBlockCacheReclaimer();
        self.background_executor.drain();
        self.waitForGenerationReadersToDrain();
        self.releaseTrackedResourceUsage();
        recovery_mod.close(Backend, self);
    }

    pub fn abandonAfterCrash(self: *Backend) void {
        self.closing.store(true, .release);
        self.detachLocalBlockCacheReclaimer();
        self.background_executor.drain();
        self.releaseTrackedResourceUsage();
        recovery_mod.abandon(Backend, self);
    }

    fn waitForGenerationReadersToDrain(self: *Backend) void {
        while (true) {
            const locked = runtime_mod.lockBackend(Backend, self);
            const active_readers = self.active_readers;
            runtime_mod.unlockBackend(Backend, self, locked);
            if (active_readers == 0) return;
            platform.time.yieldBriefly();
        }
    }

    pub fn acquireRootLockState(self: *Backend, create_if_missing: bool) !void {
        if (self.root_dir == null or self.root_lock_state != null) return;

        const root_dir = self.root_dir.?;
        if (create_if_missing) try self.storage.?.createDirPath(root_dir);
        const identity = try self.storage.?.rootIdentityAlloc(self.allocator, root_dir);
        defer self.allocator.free(identity);
        self.root_lock_state = try retainRootLockState(identity);
    }

    pub fn releaseRootLockState(self: *Backend) void {
        if (self.root_lock_state) |state| {
            releaseProcessRootLockState(state);
            self.root_lock_state = null;
        }
    }

    pub fn acquireRootWriterLock(self: *Backend) !void {
        if (self.options.backend.read_only or self.root_dir == null) return;
        if (self.root_writer_registered) return;

        const root_dir = self.root_dir.?;
        const root_state = self.root_lock_state orelse return error.LsmRootWriterLockStateMissing;
        try acquireProcessRootWriter(root_state);
        errdefer releaseProcessRootWriter(root_state);

        var native_lock: ?storage_io.NativePathLock = null;
        errdefer if (native_lock) |*lock| lock.release();

        if (self.storage.?.supportsNativePathLocks()) {
            const lock_path = try rootLockPathAlloc(self.allocator, root_dir);
            defer self.allocator.free(lock_path);
            native_lock = storage_io.acquireNativePathLockWithPool(
                self.allocator,
                lock_path,
                .exclusive,
                .{ .nonblocking = true },
                self.options.native_storage_pool,
            ) catch |err| switch (err) {
                error.WouldBlock => return error.LsmRootWriterAlreadyOpen,
                else => return err,
            };
        }

        self.root_writer_registered = true;
        self.root_writer_lock = native_lock;
        native_lock = null;
    }

    pub fn releaseRootWriterLock(self: *Backend) void {
        if (self.root_writer_lock) |*lock| {
            lock.release();
            self.root_writer_lock = null;
        }
        if (self.root_writer_registered) {
            if (self.root_lock_state) |state| releaseProcessRootWriter(state);
            self.root_writer_registered = false;
        }
    }

    pub fn prepareWalOperationLockFile(self: *Backend) !void {
        if (comptime builtin.os.tag != .freestanding) {
            if (!self.options.wal_enabled or self.root_dir == null or !self.storage.?.supportsNativePathLocks()) return;
            if (self.wal_operation_lock_file != null) return;

            const lock_path = try walOperationLockPathAlloc(self.allocator, self.root_dir.?);
            defer self.allocator.free(lock_path);
            self.wal_operation_lock_file = storage_io.openNativePathLockFileWithPool(
                self.allocator,
                lock_path,
                .{ .create_if_missing = true },
                self.options.native_storage_pool,
            ) catch |err| switch (err) {
                error.FileNotFound => if (self.options.backend.read_only) return else return err,
                else => return err,
            };
        }
    }

    pub fn closeWalOperationLockFile(self: *Backend) void {
        if (self.wal_operation_lock_file) |*lock_file| {
            lock_file.close();
            self.wal_operation_lock_file = null;
        }
    }

    const WalOperationLock = struct {
        backend: *Backend,
        process_lock_mode: ?storage_io.NativePathLockMode = null,
        native_locked: bool = false,

        pub fn release(self: *WalOperationLock) void {
            if (self.native_locked) {
                self.backend.wal_operation_lock_file.?.unlock();
                self.native_locked = false;
            }
            if (self.process_lock_mode) |mode| {
                const state = self.backend.root_lock_state.?;
                switch (mode) {
                    .shared => state.wal_rwlock.unlockShared(),
                    .exclusive => state.wal_rwlock.unlockExclusive(),
                }
                self.process_lock_mode = null;
            }
        }
    };

    fn acquireWalOperationLock(self: *Backend, mode: storage_io.NativePathLockMode) !WalOperationLock {
        var guard = WalOperationLock{ .backend = self };
        if (!self.options.wal_enabled or self.root_dir == null) return guard;

        if (self.root_lock_state) |state| {
            switch (mode) {
                .shared => state.wal_rwlock.lockShared(),
                .exclusive => state.wal_rwlock.lockExclusive(),
            }
            guard.process_lock_mode = mode;
        }
        errdefer guard.release();

        if (self.storage.?.supportsNativePathLocks()) {
            if (self.wal_operation_lock_file == null) try self.prepareWalOperationLockFile();
            if (self.wal_operation_lock_file) |*lock_file| {
                try lock_file.lock(mode);
                guard.native_locked = true;
            }
        }
        return guard;
    }

    fn tryAcquireWalOperationLock(self: *Backend, mode: storage_io.NativePathLockMode) !?WalOperationLock {
        return self.tryAcquireWalOperationLockImpl(mode, true);
    }

    fn tryAcquireWalOperationLockImpl(self: *Backend, mode: storage_io.NativePathLockMode, prepare_if_missing: bool) !?WalOperationLock {
        var guard = WalOperationLock{ .backend = self };
        if (!self.options.wal_enabled or self.root_dir == null) return guard;

        if (self.root_lock_state) |state| {
            const process_locked = switch (mode) {
                .shared => state.wal_rwlock.tryLockShared(),
                .exclusive => state.wal_rwlock.tryLockExclusive(),
            };
            if (!process_locked) return null;
            guard.process_lock_mode = mode;
        }
        errdefer guard.release();

        if (self.storage.?.supportsNativePathLocks()) {
            if (self.wal_operation_lock_file == null) {
                if (!prepare_if_missing) return error.ExecutionWaitUnsupported;
                try self.prepareWalOperationLockFile();
            }
            if (self.wal_operation_lock_file) |*lock_file| {
                if (!try lock_file.tryLock(mode)) {
                    guard.release();
                    return null;
                }
                guard.native_locked = true;
            }
        }
        return guard;
    }

    /// Owns an idle tentative grant after a publication race or pre-dispatch
    /// rejection. The backend, immutable record and its prepaid credit remain
    /// alive until retry retires this owner or explicit physical destruction.
    /// No admission borrow or payload is retained here.
    pub const QuiescedDurabilityPreparation = struct {
        resources: ?storage_io.DurabilityResources = null,
        backend: ?*Backend = null,
        record: ?[]const u8 = null,
        failure: ?anyerror = null,

        fn resumeRetirement(self: *@This(), backend: *Backend, record: ?[]const u8, original: read_admission.Port) !bool {
            if (self.resources) |*resources| {
                std.debug.assert(self.backend == backend);
                std.debug.assert((self.record == null) == (record == null));
                if (record) |bytes| std.debug.assert(self.record.?.ptr == bytes.ptr and self.record.?.len == bytes.len);
                try resources.retireWithAdmission(original);
                const failure = self.failure;
                self.* = .{};
                if (failure) |cause| return cause;
                return true;
            }
            return false;
        }

        fn reject(self: *@This(), backend: *Backend, record: ?[]const u8, resources: storage_io.DurabilityResources, failure: ?anyerror, original: read_admission.Port) !void {
            std.debug.assert(self.resources == null);
            self.* = .{ .resources = resources, .backend = backend, .record = record, .failure = failure };
            _ = try self.resumeRetirement(backend, record, original);
        }

        /// Explicit legacy fallback only; admitted rejection never calls this.
        pub fn deinit(self: *@This()) void {
            if (self.resources) |*resources| resources.deinit();
            self.* = .{};
        }
    };

    pub const QuiescedWalSync = wal_mod.CurrentStateSync(WalOperationLock);

    /// The caller has fenced this backend's writers/maintenance and retains
    /// the backend through operation retirement. No backend mutex is held
    /// while publication or physical I/O is awaited. Legacy acquirers must
    /// not occupy every CPU slot needed for this cleanup execution's reentry.
    pub fn tryBeginQuiescedWalSyncWithAdmission(self: *Backend, preparation: *QuiescedDurabilityPreparation, original: read_admission.Port) !?QuiescedWalSync {
        if (try preparation.resumeRetirement(self, null, original)) return null;
        try original.checkpoint();
        if (!self.options.wal_enabled or self.root_dir == null or self.storage == null) return error.ExecutionWaitUnsupported;
        // Opening lock files or installing root state here would introduce
        // hidden descriptor/metadata acquisition into compound publication.
        if (!self.storage.?.supportsNativePathLocks() or self.root_lock_state == null or self.wal_operation_lock_file == null)
            return error.ExecutionWaitUnsupported;
        var operation = try QuiescedWalSync.prepare(self.root_dir.?);
        // Avoid allocating a grant for an already-busy publication owner. The
        // real acquisition below still handles a race after this probe.
        var probe = (try self.tryAcquireWalOperationLockImpl(.exclusive, false)) orelse return null;
        probe.release();
        const resources = (try self.storage.?.tryPrepareDurabilityWithAdmission(original)) orelse return null;
        var publication = (self.tryAcquireWalOperationLockImpl(.exclusive, false) catch |cause| {
            try preparation.reject(self, null, resources, cause, original);
            unreachable;
        }) orelse {
            try preparation.reject(self, null, resources, null, original);
            return null;
        };
        operation.start(resources, publication, original) catch |cause| {
            publication.release();
            try preparation.reject(self, null, resources, cause, original);
            unreachable;
        };
        return operation;
    }

    pub fn beginQuiescedWalSyncWithAdmission(self: *Backend, io: std.Io, preparation: *QuiescedDurabilityPreparation, original: read_admission.Port) !QuiescedWalSync {
        while (true) {
            if (try self.tryBeginQuiescedWalSyncWithAdmission(preparation, original)) |operation| return operation;
            // Both publication and tentative completion resources are gone
            // before relinquishing CPU and waiting under the original scope.
            try @import("../common/cleanup_wait.zig").waitForRetry(io, original);
        }
    }

    /// Close owns exclusive observation as well as mutation of this backend
    /// across this continuation. All producer, reader and accounting admission
    /// must be fenced; cached-reader releases may finish before detachment.
    /// Detachment and observation allocate nothing and issue no filesystem
    /// work. Final ledger reconciliation may admit existing-usage metadata.
    pub const QuiescedClosePreflight = struct {
        const Phase = enum {
            mutable,
            fixed,
            active_ledger_reclamations,
            ledger_snapshots,
            active_compaction_publications,
            retired_run_stores,
            retired_admissions,
            active_bulk_plans,
            retired_bulk_plans,
            retired_closures,
            retired_gc,
            live_read_versions,
            retired_run_directories,
            retired_read_versions,
            retired_projection_versions,
            retired_domain_indexes,
            immutable,
            retired_immutable,
            bulk_accounts,
            cached,
            retired_mutable,
            retired_memory,
            reclaiming,
            reconcile,
            done,
        };
        backend: ?*Backend = null,
        detached: bool = false,
        pass: u64 = 0,
        phase: Phase = .mutable,
        bytes: u64 = 0,
        index: usize = 0,
        current: ?*anyopaque = null,
        initialized: bool = false,
        mutable: ActiveMemTable.Accounting = .{},
        state: State.Accounting = .{},
        batch: ?*ReclaimingMemory = null,
        version: ?*runtime_mod.ReadVersion = null,

        fn advance(self: *@This()) void {
            self.phase = @fromBackingInt(@intCast(@backingInt(self.phase) + 1));
            self.index = 0;
            self.current = null;
            self.initialized = false;
            self.state = .{};
        }

        fn detach(self: *@This(), backend: *Backend, io: std.Io, original: read_admission.Port) !bool {
            try @import("../common/cleanup_wait.zig").lockAtomic(&backend.mu, io, original);
            defer backend.mu.unlock();
            if (backend.active_readers != 0) return false;
            if (backend.mutable_read_snapshot) |snapshot| {
                const ref = backend.mutableSnapshotReaderRefIndex(snapshot) orelse unreachable;
                if (backend.mutable_snapshot_reader_refs.items[ref].readers != 0) return false;
                backend.mutable_read_snapshot = null;
                _ = backend.removeMutableSnapshotReaderRef(ref);
                // The already-owned header carries retirement. Keep it reachable
                // by legacy and admitted accounting until physical reclamation;
                // no destructor or new background job runs after durable drain.
                @import("lsm_backend/memtable_reclamation.zig").retire(backend, snapshot);
            }
            self.detached = true;
            return true;
        }

        fn fixed(self: *@This(), b: *Backend) void {
            const pass = self.pass;
            if (b.options.unpublished_outputs) |queue| self.bytes +|= queue.observedMemoryBytes();
            self.bytes +|= b.runs.memoryBytes(pass);
            if (b.store_reclaimer) |*job| self.bytes +|= @sizeOf(RunStore) +| job.store.memoryBytes(pass);
            inline for (.{ "run_directory", "manifest_directory", "manifest_checkpoint_directory" }) |field|
                if (@field(b, field)) |directory| {
                    self.bytes +|= directory.accountedMemoryBytes(pass);
                };
            inline for (.{ "pending_directory_closure", "pending_l0_directory_closure" }) |field|
                if (@field(b, field)) |pending| {
                    self.bytes +|= pending.directory.accountedMemoryBytes(pass);
                };
            for (b.pending_admissions) |pending| if (pending) |job| {
                self.bytes +|= job.accountedMemoryBytes(pass);
            };
            if (b.pending_tombstone_reconcile) |pending| self.bytes +|= pending.account.chargeOnce(pass);
            if (b.pending_gc) |pending| self.bytes +|= pending.accountedMemoryBytes(pass);
            self.bytes +|= b.manifest_journal.obsolete.memoryBytes(pass);
            self.bytes +|= b.obsolete_paths.memoryBytes(pass);
            if (b.obsolete_reclaim_after) |path| self.bytes +|= path.len;
            if (b.directory_reclaimer) |*job| self.bytes +|= job.directory.accountedMemoryBytes(pass);
            if (b.domain_index) |value| self.bytes +|= value.memoryBytes();
            if (b.read_metadata_reclaimer) |*job| self.bytes +|= job.memoryBytes(pass);
            self.bytes +|= b.bulk_snapshot_unshared_bytes;
            if (b.memtable_reclaimer) |*job| self.bytes +|= job.memoryBytes(pass);
        }

        fn list(self: *@This(), b: *Backend, comptime phase: Phase) void {
            const field = @tagName(phase);
            const Pointer = @typeInfo(@FieldType(Backend, field)).optional.child;
            const next = switch (phase) {
                .active_ledger_reclamations, .active_compaction_publications => "next",
                .ledger_snapshots, .active_bulk_plans => "active_next",
                .live_read_versions => "live_next",
                else => "retired_next",
            };
            if (!self.initialized) {
                self.current = @field(b, field);
                self.initialized = true;
            }
            if (self.current) |raw| {
                const node: Pointer = @ptrCast(@alignCast(raw));
                self.bytes +|= switch (phase) {
                    .active_ledger_reclamations, .ledger_snapshots => node.memoryBytes(self.pass),
                    .retired_run_stores => @sizeOf(RunStore) +| node.memoryBytes(self.pass),
                    .retired_domain_indexes => node.memoryBytes(),
                    .retired_closures => node.directory.accountedMemoryBytes(self.pass),
                    else => node.accountedMemoryBytes(self.pass),
                };
                self.current = @field(node, next);
            } else self.advance();
        }

        fn stateStep(self: *@This(), value: *const State) bool {
            var credits: usize = 64;
            if (!self.state.step(value, self.pass, &credits)) return false;
            self.bytes +|= self.state.bytes;
            self.state = .{};
            return true;
        }

        pub fn resumeWithAdmission(self: *@This(), b: *Backend, io: std.Io, original: read_admission.Port) !void {
            try original.checkpoint();
            if (self.backend) |bound| std.debug.assert(bound == b) else self.backend = b;
            while (!self.detached) {
                if (!try self.detach(b, io, original))
                    try @import("../common/cleanup_wait.zig").waitForRetry(io, original);
            }
            if (self.pass == 0) self.pass = state_mod.memory_account.nextPass();
            while (self.phase != .done) {
                try original.checkpoint();
                switch (self.phase) {
                    .mutable => {
                        var credits: usize = 64;
                        if (self.mutable.step(&b.mutable, self.pass, &credits)) {
                            self.bytes +|= self.mutable.bytes;
                            self.advance();
                        }
                    },
                    .fixed => {
                        self.fixed(b);
                        self.advance();
                    },
                    inline .active_ledger_reclamations, .ledger_snapshots, .active_compaction_publications, .retired_run_stores, .retired_admissions, .active_bulk_plans, .retired_bulk_plans, .retired_closures, .retired_gc, .live_read_versions, .retired_run_directories, .retired_read_versions, .retired_projection_versions, .retired_domain_indexes => |phase| self.list(b, phase),
                    .immutable, .retired_immutable, .retired_mutable => {
                        const items = switch (self.phase) {
                            .immutable => b.activeImmutableMemtables(),
                            .retired_immutable => b.retired_immutable_memtables.items,
                            .retired_mutable => b.retired_mutable_snapshots.items,
                            else => unreachable,
                        };
                        if (self.index == items.len) self.advance() else if (self.stateStep(items[self.index])) self.index += 1;
                    },
                    .bulk_accounts => {
                        const accounts = &b.bulk_snapshot_accounts;
                        if (accounts.count() == 0 or self.index == accounts.capacity()) {
                            self.advance();
                        } else {
                            // Iterator.next() can scan a sparse table without a
                            // checkpoint. Enter it only at occupied slots, so
                            // it returns immediately; inspect at most 64 slots.
                            const end = @min(accounts.capacity(), self.index + 64);
                            while (self.index < end) : (self.index += 1) {
                                if (accounts.metadata.?[self.index].isUsed()) {
                                    var iterator = accounts.iterator();
                                    iterator.index = @intCast(self.index);
                                    const entry = iterator.next().?;
                                    self.bytes +|= entry.key_ptr.*.chargeOnce(self.pass);
                                }
                            }
                        }
                    },
                    .cached => {
                        if (b.mutable_read_snapshot) |snapshot| {
                            if (self.stateStep(snapshot)) self.advance();
                        } else self.advance();
                    },
                    .retired_memory => {
                        if (!self.initialized) {
                            self.current = b.retired_memory_head;
                            self.initialized = true;
                        }
                        if (self.current) |raw| {
                            const value: *State = @ptrCast(@alignCast(raw));
                            if (self.stateStep(value)) {
                                self.bytes +|= @sizeOf(State);
                                self.current = value.retired_next;
                            }
                        } else self.advance();
                    },
                    .reclaiming => {
                        if (!self.initialized) {
                            self.batch = b.reclaiming_memory;
                            self.version = if (self.batch) |batch| batch.versions else null;
                            self.initialized = true;
                        }
                        if (self.version) |version| {
                            self.bytes +|= version.accountedMemoryBytes(self.pass);
                            self.version = version.retired_next;
                        } else if (self.batch) |batch| {
                            self.batch = batch.next;
                            self.version = if (self.batch) |next| next.versions else null;
                        } else self.advance();
                    },
                    .reconcile => {
                        std.debug.assert(b.active_readers == 0 and b.mutable_read_snapshot == null);
                        if (b.options.resource_manager) |manager|
                            try manager.adjustUsageWithAdmission(.lsm_in_memory_state, &b.tracked_in_memory_state_bytes, self.bytes, original);
                        self.advance();
                    },
                    .done => unreachable,
                }
            }
        }
    };

    /// Reclaim obsolete memory before close needs final persistence headroom.
    /// Serving, producer and accounting admission must remain permanently
    /// fenced. Only retired queues are consumed; live mutable/immutable data,
    /// ledger roots and durable finalization obligations remain backend-owned.
    /// The original finite execution is borrowed on each call, never retained.
    pub const QuiescedClosePreparation = struct {
        phase: enum { observe, memtables, metadata, ledgers, reconcile, done } = .observe,
        before: QuiescedClosePreflight = .{},
        after: QuiescedClosePreflight = .{},

        pub fn resumeWithAdmission(self: *@This(), backend: *Backend, io: std.Io, original: read_admission.Port) !void {
            try original.checkpoint();
            if (self.before.backend) |bound| std.debug.assert(bound == backend);
            while (self.phase != .done) {
                try original.checkpoint();
                switch (self.phase) {
                    .observe => {
                        // Establish the full retained charge before destroying
                        // anything, including cold legacy snapshot accounting.
                        try self.before.resumeWithAdmission(backend, io, original);
                        if (backend.memtable_reclaimer == null and backend.retired_memory_head == null and backend.retired_ledger_snapshots == null and !@import("lsm_backend/read_metadata_reclamation.zig").pending(backend)) {
                            // No physical ownership changed. Reuse the first
                            // observation instead of scanning live state twice.
                            self.after = self.before;
                            self.phase = .done;
                        } else self.phase = .memtables;
                    },
                    .memtables => {
                        var credits: usize = 64;
                        if (@import("lsm_backend/memtable_reclamation.zig").reclaimQuiescedStep(backend, &credits)) self.phase = .metadata;
                    },
                    .metadata => {
                        try @import("lsm_backend/read_metadata_reclamation.zig").reclaimWithAdmission(backend, original);
                        self.phase = .ledgers;
                    },
                    .ledgers => {
                        var credits: usize = 64;
                        if (@import("lsm_backend/ledger_reclamation.zig").reclaimQuiescedStep(backend, &credits)) self.phase = .reconcile;
                    },
                    .reconcile => {
                        // Shared allocation accounts may still be referenced
                        // by live generations. Reobserve once in bounded CPU
                        // slices; never subtract a whole retired generation or
                        // rescan the backend after every destructor quantum.
                        try self.after.resumeWithAdmission(backend, io, original);
                        self.phase = .done;
                    },
                    .done => unreachable,
                }
            }
        }
    };

    /// Own construction credit and a bounded mutable successor through WAL
    /// publication and old-state retirement. The backend, its observed usage
    /// identity and every unrelated account mutation must remain quiesced and
    /// stable until this owner retires. Input/WAL residency is prepaid by their
    /// respective owners; this reservation covers additional successor bytes.
    /// The caller first reconciles existing backend usage while quiescing it;
    /// this delta owner cannot repair unobserved legacy allocations. Default
    /// controlled close must detach cached mutable snapshots and establish
    /// that baseline on admitted CPU before creating this owner.
    pub const QuiescedMutablePublication = struct {
        const Account = state_mod.memory_account.Account;
        backend: *Backend,
        cpu: ActiveMemTable.PublicationPreparation,
        credit: ?resource_manager_mod.ConstructionCredit = null,
        meter: ?*Account,
        baseline_account_bytes: u64,
        baseline_spare_bytes: u64,
        baseline_usage: u64,
        adopted: bool = false,
        retirement_usage: ?u64 = null,
        retired: bool = false,

        pub fn init(backend: *Backend, source: *State) @This() {
            std.debug.assert(backend.mutable_read_snapshot == null);
            const account = backend.mutable.ordered.account;
            const bytes = if (account) |a| a.bytes.load(.acquire) else 0;
            const spares = spareBytes(&backend.mutable);
            if (backend.options.resource_manager != null) {
                const queue = if (backend.options.unpublished_outputs) |q| q.observedMemoryBytes() else 0;
                std.debug.assert(backend.tracked_in_memory_state_bytes >= bytes + spares + queue);
            }
            return .{
                .backend = backend,
                .cpu = .init(&backend.mutable, source),
                .meter = if (account) |a| a.retain() else null,
                .baseline_account_bytes = bytes,
                .baseline_spare_bytes = spares,
                .baseline_usage = backend.tracked_in_memory_state_bytes,
            };
        }

        fn spareBytes(table: *const ActiveMemTable) u64 {
            return table.ordered.spare.capacity * @sizeOf(*anyopaque);
        }

        fn pinMeter(self: *@This()) void {
            if (self.meter == null) {
                if (self.cpu.candidate.ordered.account) |a| self.meter = a.retain();
            }
        }

        pub fn resumeWithAdmission(self: *@This(), original: read_admission.Port) !void {
            std.debug.assert(!self.retired and self.retirement_usage == null and !self.cpu.published);
            const bound = try self.cpu.memoryBoundWithAdmission(original);
            if (self.backend.options.resource_manager) |manager| {
                try manager.prepareUsageWithAdmission(.lsm_in_memory_state, &self.backend.tracked_in_memory_state_bytes, original);
                if (self.credit == null)
                    self.credit = try manager.reserveConstructionWithAdmission(.lsm_table_builder_working_set, bound, original);
            }
            self.cpu.resumeWithAdmission(self.backend.allocator, original) catch |cause| {
                self.pinMeter();
                return cause;
            };
            self.pinMeter();
            if (!self.adopted) {
                const bytes = if (self.meter) |a| a.bytes.load(.acquire) else 0;
                std.debug.assert(bytes >= self.baseline_account_bytes);
                const added = bytes - self.baseline_account_bytes + spareBytes(&self.cpu.candidate);
                std.debug.assert(added <= bound);
                if (self.credit) |*credit| {
                    if (added != 0) try credit.adoptUsageWithAdmission(.lsm_in_memory_state, &self.backend.tracked_in_memory_state_bytes, added, original);
                }
                self.adopted = true;
            }
        }

        /// Called only by the owning WAL coordinator's infallible callback.
        /// No ledger lock, observer scan or retirement can occur here.
        pub fn publish(self: *@This()) void {
            std.debug.assert(self.adopted and !self.retired);
            std.debug.assert(self.backend.mutable_read_snapshot == null);
            self.cpu.publish(&self.backend.mutable);
        }

        fn finishPhysicalRetirement(self: *@This()) void {
            if (self.retirement_usage != null) return;
            std.debug.assert(self.cpu.retired);
            const current_account = self.backend.mutable.ordered.account;
            const bytes = if (current_account) |a| blk: {
                std.debug.assert(a == self.meter.?);
                break :blk a.bytes.load(.acquire);
            } else blk: {
                if (self.meter) |a| std.debug.assert(a.bytes.load(.acquire) == @sizeOf(Account));
                break :blk @as(u64, 0);
            };
            self.retirement_usage = if (self.backend.options.resource_manager != null)
                self.baseline_usage - self.baseline_account_bytes - self.baseline_spare_bytes + bytes + spareBytes(&self.backend.mutable)
            else
                0;
            // Free a speculative account header before making its capacity
            // available. A rejected ledger retry retains the target and charge.
            if (self.meter) |a| a.release();
            self.meter = null;
        }

        pub fn retireWithAdmission(self: *@This(), original: read_admission.Port) !void {
            try original.checkpoint();
            if (self.retired) return;
            self.pinMeter();
            try self.cpu.retireWithAdmission(self.backend.allocator, original);
            self.finishPhysicalRetirement();
            if (self.backend.options.resource_manager) |manager| {
                const next = self.retirement_usage.?;
                std.debug.assert(next <= self.backend.tracked_in_memory_state_bytes);
                try manager.adjustUsageWithAdmission(.lsm_in_memory_state, &self.backend.tracked_in_memory_state_bytes, next, original);
            }
            if (self.credit) |*credit| credit.retire();
            self.credit = null;
            self.retired = true;
        }

        /// Mandatory quiesced fallback after the owning WAL operation joins.
        pub fn deinit(self: *@This()) void {
            if (self.retired) return;
            self.pinMeter();
            self.cpu.deinit(self.backend.allocator);
            self.finishPhysicalRetirement();
            if (self.backend.options.resource_manager) |manager|
                std.debug.assert(manager.tryObserveUsage(.lsm_in_memory_state, &self.backend.tracked_in_memory_state_bytes, self.retirement_usage.?));
            if (self.credit) |*credit| credit.retire();
            self.credit = null;
            self.retired = true;
        }
    };

    /// Payload owns a prepared bounded CPU publication and its credits. It
    /// provides publish(AppendResult), requireRecovery() and release(). The
    /// caller fences all same-backend writers/readers/maintenance and retains
    /// the backend until operation retirement, just as for QuiescedWalSync.
    pub fn QuiescedWalAppend(comptime Payload: type) type {
        return wal_mod.CurrentStateAppend(struct {
            backend: *Backend,
            guard: WalOperationLock,
            payload: Payload,
            entries: u32,
            pub fn publish(self: *@This(), result: wal_mod.AppendResult) void {
                self.payload.publish(result);
                // Invalidate scalar cache generations without scanning or
                // allocating while this prepared publication is adopted.
                self.backend.wal_retention.invalidateAll();
                self.backend.noteMutableWalSegment(result.segment);
                self.backend.write_stats.wal_append_records += 1;
                self.backend.write_stats.wal_append_entries += self.entries;
                self.backend.write_stats.wal_append_bytes += result.bytes;
                self.backend.write_stats.wal_segment_syncs += result.segment_syncs;
                self.backend.write_stats.wal_index_syncs += result.index_syncs;
                self.backend.write_stats.wal_sync_records += 1;
            }
            pub fn requireRecovery(self: *@This()) void {
                self.backend.manifest_recovery_required = true;
                self.backend.wal_retention.invalidateAll();
                self.payload.requireRecovery();
            }
            pub fn release(self: *@This()) void {
                self.payload.release();
                self.guard.release();
            }
        });
    }

    /// A failed try/initial dispatch leaves Payload with the caller. Prepared
    /// append bytes and descriptor/worker credit precede publication acquisition;
    /// a busy guard retires the tentative grant under the original execution
    /// before waiting for publication. Rejection retains the preparation.
    pub fn tryBeginQuiescedWalAppendWithAdmission(self: *Backend, preparation: *QuiescedDurabilityPreparation, record: []const u8, payload: anytype, original: read_admission.Port) !?QuiescedWalAppend(@TypeOf(payload)) {
        if (try preparation.resumeRetirement(self, record, original)) return null;
        try original.checkpoint();
        if (self.options.backend.read_only) return error.ReadOnly;
        if (self.manifest_recovery_required) return error.RecoveryRequired;
        if (!self.options.wal_enabled or self.root_dir == null or self.storage == null or
            !self.storage.?.supportsNativePathLocks() or self.root_lock_state == null or self.wal_operation_lock_file == null)
            return error.ExecutionWaitUnsupported;
        const entries = try wal_mod.validateStateRecordWithAdmission(record, original);
        if (entries == 0) return error.ResourceBudgetExceeded;
        var operation = try QuiescedWalAppend(@TypeOf(payload)).prepare(self.root_dir.?, record.len, .{ .segment_bytes = self.options.wal_segment_bytes });
        var probe = (try self.tryAcquireWalOperationLockImpl(.exclusive, false)) orelse return null;
        probe.release();
        const resources = (try self.storage.?.tryPrepareAppendWithAdmission(record, original)) orelse return null;
        var guard = (self.tryAcquireWalOperationLockImpl(.exclusive, false) catch |cause| {
            try preparation.reject(self, record, resources, cause, original);
            unreachable;
        }) orelse {
            try preparation.reject(self, record, resources, null, original);
            return null;
        };
        operation.start(resources, .{ .backend = self, .guard = guard, .payload = payload, .entries = entries }, original) catch |cause| {
            guard.release();
            try preparation.reject(self, record, resources, cause, original);
            unreachable;
        };
        return operation;
    }

    pub fn beginQuiescedWalAppendWithAdmission(self: *Backend, io: std.Io, preparation: *QuiescedDurabilityPreparation, record: []const u8, payload: anytype, original: read_admission.Port) !QuiescedWalAppend(@TypeOf(payload)) {
        while (true) {
            if (try self.tryBeginQuiescedWalAppendWithAdmission(preparation, record, payload, original)) |operation| return operation;
            try @import("../common/cleanup_wait.zig").waitForRetry(io, original);
        }
    }

    fn resolveBackgroundExecutor(configured: ?*const BackgroundExecutor) BackgroundExecutor {
        return if (configured) |executor| executor.* else BackgroundExecutor.initInline(0);
    }

    pub fn sync(self: *Backend, force: bool) !void {
        if (self.root_dir == null) return;
        const locked = runtime_mod.lockBackend(Backend, self);
        defer runtime_mod.unlockBackend(Backend, self, locked);
        if (force and !self.options.backend.read_only and self.options.wal_enabled) {
            var wal_lock = try self.acquireWalOperationLock(.exclusive);
            defer wal_lock.release();
            _ = try wal_mod.syncCurrentState(self.storage.?, self.allocator, self.root_dir.?);
        }
        try self.finalizeDeferredStorageWorkLocked();
    }

    /// Request reclamation of superseded values in the current persisted runs.
    /// The caller flushes replacement values first. Only metadata is prepared
    /// here; the regular admitted, streaming GC jobs rewrite overlap closures.
    /// The manifest intent survives restart, partial compaction and old readers.
    pub fn requestValueReclamation(self: *Backend) !void {
        const locked = runtime_mod.lockBackend(Backend, self);
        defer runtime_mod.unlockBackend(Backend, self, locked);
        if (self.options.backend.read_only) return error.ReadOnly;
        const current = try self.planningDirectory();
        var wire: u64 = 128;
        var scratch: u64 = 8192;
        const height: u64 = if (current.tree.root) |root| root.height else 1;
        var cursor = self.runs.cursor();
        while (cursor.next()) |run| {
            if (run.gc_requested) continue;
            const names = run.smallest_key.len + run.largest_key.len +
                (if (run.path) |path| path.len else 0) +
                (if (run.smallest_namespace_name) |name| name.len else 0) +
                (if (run.largest_namespace_name) |name| name.len else 0);
            wire +|= 192 +| names;
            // Bound the administrative metadata clones before allocation.
            scratch +|= (height + 1) * 16384 +| names * 2 +|
                (if (run.state) |*state| state.estimatedMemoryBytes() else 0);
        }
        var reservation: ?resource_manager_mod.Reservation = null;
        defer if (reservation) |*lease| lease.release();
        if (self.options.resource_manager) |manager|
            reservation = try manager.reserve(.lsm_table_builder_working_set, scratch);
        var credit = try self.admitCompactionMetadataBytes(wire);
        defer credit.release();
        const directory = try current.fork(self.allocator);
        var directory_owned = true;
        defer if (directory_owned) directory.destroy(self.allocator);
        const store = try self.allocator.create(RunStore);
        store.* = self.runs.fork();
        defer self.retireRunStore(store);
        cursor = self.runs.cursor();
        while (cursor.next()) |run| {
            if (run.gc_requested) continue;
            var revision = RunStore.revision(run, run.*);
            revision.gc_requested = true;
            try store.stageRevision(self.allocator, revision);
            store.adopt(&revision);
            try directory.put(self, revision);
        }
        std.mem.swap(RunStore, &self.runs, store);
        self.invalidateReadVersion();
        self.publishRunDirectory(directory);
        directory_owned = false;
        credit.commit();
        self.markManifestDirty();
        try self.persistManifestLocked();
        self.notePotentialMaintenanceDebtLocked();
    }

    pub fn hasValueReclamationRequests(self: *Backend) !bool {
        const locked = runtime_mod.lockBackend(Backend, self);
        defer runtime_mod.unlockBackend(Backend, self, locked);
        return (try self.planningDirectory()).hasGcRequest();
    }

    pub fn syncReplayState(self: *Backend) !void {
        _ = try self.syncReplayStateWithStats();
    }

    pub fn syncReplayStateWithStats(self: *Backend) !wal_mod.SyncResult {
        if (self.root_dir == null) return .{};
        const locked = runtime_mod.lockBackend(Backend, self);
        defer runtime_mod.unlockBackend(Backend, self, locked);
        if (!self.options.backend.read_only and self.options.wal_enabled) {
            var wal_lock = try self.acquireWalOperationLock(.exclusive);
            defer wal_lock.release();
            return try wal_mod.syncCurrentState(self.storage.?, self.allocator, self.root_dir.?);
        }
        try self.finalizeDeferredStorageWorkLocked();
        return .{};
    }

    pub const NativeCheckpoint = struct {
        allocator: Allocator,
        storage: storage_io.Storage,
        manifest_bytes: []u8,
        run_ids: []u64,
        run_paths: [][]u8,
        run_sizes: []u64,

        /// Persist the retained generation using immutable file links. Unlike
        /// process-local run refs, this tree survives owner restart and GC.
        pub fn seal(self: *const NativeCheckpoint, io: std.Io, destination_root: []const u8, cancellation: CancellationToken) !u64 {
            if (!self.storage.supportsHostPathGenerationPublication()) return error.NativeBackupStorageBackendUnsupported;
            try fs_paths.createDirPathPortable(io, destination_root);
            const manifest = try std.fmt.allocPrint(self.allocator, "{s}/manifest.bin", .{destination_root});
            defer self.allocator.free(manifest);
            var total = try writeCheckpointBytes(io, manifest, self.manifest_bytes, null);
            const runs = try std.fmt.allocPrint(self.allocator, "{s}/runs", .{destination_root});
            defer self.allocator.free(runs);
            try fs_paths.createDirPathPortable(io, runs);
            for (self.run_paths, self.run_ids) |source, id| {
                try cancellation.check();
                const target = try std.fmt.allocPrint(self.allocator, "{s}/{d}.tbl", .{ runs, id });
                defer self.allocator.free(target);
                try std.Io.Dir.hardLink(.cwd(), source, .cwd(), target, io, .{});
                var file = try std.Io.Dir.cwd().openFile(io, target, .{});
                defer file.close(io);
                const stat = try file.stat(io);
                if (stat.kind != .file) return error.UnsupportedFileType;
                total = std.math.add(u64, total, stat.size) catch return error.FileTooBig;
            }
            try fs_paths.syncDirPortable(io, runs);
            try fs_paths.syncDirPortable(io, destination_root);
            return total;
        }

        pub fn deinit(self: *NativeCheckpoint) void {
            for (self.run_paths) |path| {
                run_snapshot_refs.release(path);
                self.allocator.free(path);
            }
            self.allocator.free(self.run_paths);
            self.allocator.free(self.run_ids);
            self.allocator.free(self.run_sizes);
            self.allocator.free(self.manifest_bytes);
            self.* = undefined;
        }

        pub fn materialize(
            self: *const NativeCheckpoint,
            io: std.Io,
            destination_root: []const u8,
            cancellation: CancellationToken,
        ) !u64 {
            return try self.materializeWithSink(io, destination_root, cancellation, null);
        }

        pub fn materializeWithSink(
            self: *const NativeCheckpoint,
            io: std.Io,
            destination_root: []const u8,
            cancellation: CancellationToken,
            sink: ?native_artifact_sink.Sink,
        ) !u64 {
            try cancellation.check();
            try fs_paths.createDirPathPortable(io, destination_root);
            const manifest_path = try std.fmt.allocPrint(self.allocator, "{s}/manifest.bin", .{destination_root});
            defer self.allocator.free(manifest_path);
            var total = try writeCheckpointBytes(io, manifest_path, self.manifest_bytes, sink);
            for (self.run_paths, self.run_ids) |source, run_id| {
                try cancellation.check();
                const destination = try std.fmt.allocPrint(self.allocator, "{s}/runs/{d}.tbl", .{ destination_root, run_id });
                defer self.allocator.free(destination);
                total = std.math.add(
                    u64,
                    total,
                    try copyCheckpointStorageFile(
                        self.allocator,
                        self.storage,
                        io,
                        source,
                        destination,
                        cancellation,
                        sink,
                    ),
                ) catch return error.FileTooBig;
            }
            if (self.run_paths.len > 0) {
                const runs_directory = try std.fmt.allocPrint(self.allocator, "{s}/runs", .{destination_root});
                defer self.allocator.free(runs_directory);
                try fs_paths.syncDirPortable(io, runs_directory);
            }
            try fs_paths.syncDirPortable(io, destination_root);
            return total;
        }
    };

    /// Pins a fully manifested immutable LSM generation. Mutable state is
    /// flushed while the caller owns the DB revision fence; copying run bytes
    /// happens later and obsolete-file reclamation observes the snapshot refs.
    pub fn pinNativeCheckpoint(self: *Backend) !NativeCheckpoint {
        const root_dir = self.root_dir orelse return error.Unsupported;
        const storage = self.storage orelse return error.Unsupported;
        if (self.options.backend.read_only) return error.ReadOnly;
        const locked = runtime_mod.lockBackend(Backend, self);
        defer runtime_mod.unlockBackend(Backend, self, locked);

        try self.flushCheckpointCutLocked();
        if (self.manifest_dirty or self.obsolete_manifest_dirty or self.manifest_backing == null) {
            try self.writeManifestSnapshotLocked(root_dir, self.writeStatsNowNs());
        }
        // Export only the pinned generation, not a live edit stream or its
        // obsolete-file history. Restores need no journal suffix or old SSTs.
        const export_runs = try self.runs.project(self.allocator);
        defer self.allocator.free(export_runs);
        const manifest_bytes = try repository_mod.encodeManifestAlloc(self.allocator, self.next_run_id, export_runs, &.{});
        errdefer self.allocator.free(manifest_bytes);
        const run_ids = try self.allocator.alloc(u64, self.runs.count());
        errdefer self.allocator.free(run_ids);
        const run_sizes = try self.allocator.alloc(u64, self.runs.count());
        errdefer self.allocator.free(run_sizes);
        const run_paths = try self.allocator.alloc([]u8, self.runs.count());
        var initialized: usize = 0;
        errdefer {
            for (run_paths[0..initialized]) |path| {
                run_snapshot_refs.release(path);
                self.allocator.free(path);
            }
            self.allocator.free(run_paths);
        }
        for (export_runs, 0..) |run, index| {
            const source = run.path orelse return error.InvalidTableFile;
            const owned = try self.allocator.dupe(u8, source);
            errdefer self.allocator.free(owned);
            try run_snapshot_refs.retain(owned);
            run_ids[index] = run.id;
            run_sizes[index] = run.size_bytes;
            run_paths[index] = owned;
            initialized += 1;
        }
        return .{
            .allocator = self.allocator,
            .storage = storage,
            .manifest_bytes = manifest_bytes,
            .run_ids = run_ids,
            .run_paths = run_paths,
            .run_sizes = run_sizes,
        };
    }

    pub fn commitProvidesDurability(self: *const Backend) bool {
        return self.root_dir != null and
            !self.options.backend.read_only and
            self.options.wal_enabled and
            self.options.wal_sync_on_commit;
    }

    pub fn snapshotReadStats(self: *const Backend) ReadStats {
        return self.read_stats.snapshot();
    }

    pub fn snapshotWriteStats(self: *const Backend) WriteStats {
        const mutable = @constCast(self);
        const locked = runtime_mod.lockBackend(Backend, mutable);
        defer runtime_mod.unlockBackend(Backend, mutable, locked);
        return self.write_stats;
    }

    pub fn snapshotOpenStats(self: *const Backend) OpenStats {
        return self.open_stats;
    }

    pub fn openStatsNowNs(_: *Backend) u64 {
        return platform_time.monotonicNs();
    }

    pub fn beginOpenPhase(self: *Backend, phase: OpenPhase) u64 {
        const now = self.openStatsNowNs();
        if (self.open_stats.started == 0) {
            self.open_stats.started = 1;
            self.open_stats.total_ns = now;
        }
        self.open_stats.phase = phase;
        return now;
    }

    pub fn finishOpenPhase(self: *Backend, phase: OpenPhase, start_ns: u64) void {
        const elapsed = self.openStatsElapsedNs(start_ns);
        switch (phase) {
            .initializing_storage => self.open_stats.initializing_storage_ns +|= elapsed,
            .cleaning_recovered_run_temps => self.open_stats.cleaning_recovered_run_temps_ns +|= elapsed,
            .opening_manifest => self.open_stats.opening_manifest_ns +|= elapsed,
            .ensuring_dirs => self.open_stats.ensuring_dirs_ns +|= elapsed,
            .replaying_wal => self.open_stats.replaying_wal_ns +|= elapsed,
            .mounting_runs => self.open_stats.mounting_runs_ns +|= elapsed,
            .idle, .ready, .failed => {},
        }
    }

    pub fn recordRecoveredRunFileCleanup(self: *Backend, stats: RecoveredRunFileCleanupStats, before_wal_replay: bool) void {
        self.open_stats.recovered_table_temp_files_deleted +|= stats.files_deleted;
        self.open_stats.recovered_table_temp_bytes_deleted +|= stats.bytes_deleted;
        if (before_wal_replay) {
            self.open_stats.recovered_table_temp_files_deleted_before_replay +|= stats.files_deleted;
            self.open_stats.recovered_table_temp_bytes_deleted_before_replay +|= stats.bytes_deleted;
        }
    }

    pub fn recordOpenManifestLoaded(self: *Backend, loaded_manifest: bool) void {
        self.open_stats.loaded_manifest = loaded_manifest;
        self.open_stats.loaded_runs = @intCast(self.runs.count());
        self.open_stats.obsolete_paths = @intCast(self.obsolete_paths.count());
        self.current_manifest_bytes = if (self.recovered_manifest) |recovered| recovered.valid_bytes else if (self.manifest_backing) |raw| @intCast(raw.len) else 0;
    }

    pub fn recordOpenReplayComplete(self: *Backend) void {
        self.open_stats.mutable_entries_after_replay = @intCast(self.mutable.entryCount());
        self.open_stats.immutable_memtables_after_replay = @intCast(self.activeImmutableMemtableCount());
        self.open_stats.wal_replay_records = self.write_stats.wal_replay_records;
        self.open_stats.wal_replay_entries = self.write_stats.wal_replay_entries;
        self.open_stats.wal_replay_bytes = self.write_stats.wal_replay_bytes;
        self.open_stats.wal_replay_ns = self.write_stats.wal_replay_ns;
        self.open_stats.wal_replay_truncated_tail_bytes = self.write_stats.wal_replay_truncated_tail_bytes;
    }

    pub fn finishOpenSuccess(self: *Backend) void {
        self.open_stats.phase = .ready;
        self.open_stats.completed = 1;
        self.open_stats.failed = 0;
        self.open_stats.total_ns = self.openStatsElapsedNs(self.open_stats.total_ns);
    }

    pub fn finishOpenFailure(self: *Backend) void {
        self.open_stats.phase = .failed;
        self.open_stats.failed = 1;
        if (self.open_stats.total_ns != 0) {
            self.open_stats.total_ns = self.openStatsElapsedNs(self.open_stats.total_ns);
        }
    }

    fn openStatsElapsedNs(self: *Backend, start_ns: u64) u64 {
        const end_ns = self.openStatsNowNs();
        return if (end_ns >= start_ns) end_ns - start_ns else 0;
    }

    /// Files tracked by one captured run/cleanup inventory, not filesystem
    /// allocated blocks or a globally atomic disk snapshot. Active SSTs are
    /// pinned; obsolete files may disappear while they are measured. Live
    /// manifests, unpublished outputs and unrelated files are excluded.
    pub const PhysicalUsage = struct {
        active_sst_bytes: u64 = 0,
        obsolete_file_bytes: u64 = 0,
        wal_retained_bytes: u64 = 0,
        missing_obsolete_files: u64 = 0,

        pub fn totalBytes(self: PhysicalUsage) !u64 {
            return std.math.add(u64, try std.math.add(u64, self.active_sst_bytes, self.obsolete_file_bytes), self.wal_retained_bytes);
        }
    };

    /// Explicit filesystem measurement, not a hot-path statistics getter.
    /// Capture immutable metadata roots under the backend lock without cloning
    /// the mutable memtable. SST/obsolete stat calls run off-lock, and cleanup
    /// continues independently. Only missing obsolete files count as zero;
    /// missing active SSTs and all other I/O errors remain failures.
    pub fn measurePhysicalUsage(self: *Backend) !PhysicalUsage {
        const LedgerSnapshot = @import("lsm_backend/ledger_reclamation.zig").Snapshot;
        const captured = blk: {
            const locked = runtime_mod.lockBackend(Backend, self);
            defer runtime_mod.unlockBackend(Backend, self, locked);
            const storage = self.storage orelse return .{};
            var wal_bytes: u64 = 0;
            if (self.options.wal_enabled and self.root_dir != null) {
                wal_bytes = try std.math.add(u64, (try self.cachedWalRetentionLocked()).bytes, (try self.cachedWalReplayRetentionLocked()).bytes);
            }
            const obsolete = try LedgerSnapshot.capture(self, &self.obsolete_paths);
            errdefer obsolete.retire(self);
            const version = try self.createReadVersionFromDirectory();
            _ = version.references.fetchAdd(1, .monotonic);
            self.read_version_pins +|= 1;
            self.retainReaderKind(.other);
            break :blk .{ .storage = storage, .obsolete = obsolete, .version = version, .wal_bytes = wal_bytes };
        };
        defer {
            const locked = runtime_mod.lockBackend(Backend, self);
            defer runtime_mod.unlockBackend(Backend, self, locked);
            captured.obsolete.retire(self);
            captured.version.release(self);
            self.releaseReaderKind(.other);
        }
        var result = PhysicalUsage{ .wal_retained_bytes = captured.wal_bytes };
        const directory = captured.version.directory.?;
        var runs = directory.readCursor();
        while (runs.next()) |handle| if (handle.run.path) |path| {
            result.active_sst_bytes = try std.math.add(u64, result.active_sst_bytes, try captured.storage.fileSize(path));
        };
        var obsolete = captured.obsolete.value.iterator();
        while (obsolete.next()) |entry| {
            // A recovery ledger may still mention an active run. Account for
            // it once, against the captured directory rather than live state.
            if (parseRunIdFromTableFileName(std.fs.path.basename(entry.path))) |id| {
                if (directory.byId(id)) |run| if (run.path) |path| {
                    if (std.mem.eql(u8, path, entry.path)) continue;
                };
            }
            const bytes = captured.storage.fileSize(entry.path) catch |err| switch (err) {
                error.FileNotFound => {
                    result.missing_obsolete_files += 1;
                    continue;
                },
                else => return err,
            };
            result.obsolete_file_bytes = try std.math.add(u64, result.obsolete_file_bytes, bytes);
        }
        return result;
    }

    pub fn snapshotMaintenanceStats(self: *const Backend) MaintenanceStats {
        const mutable: *Backend = @constCast(self);
        const locked = runtime_mod.lockBackend(Backend, mutable);
        defer runtime_mod.unlockBackend(Backend, mutable, locked);
        return mutable.snapshotMaintenanceStatsLocked();
    }

    fn snapshotMaintenanceStatsLocked(self: *Backend) MaintenanceStats {
        return self.snapshotMaintenanceStatsLockedWithOptions(true);
    }

    fn snapshotMaintenanceStatsLockedWithOptions(self: *Backend, include_retention: bool) MaintenanceStats {
        var stats = MaintenanceStats{
            .read_version_builds = self.read_version_builds,
            .domain_index_builds = self.domain_index_builds,
            .read_version_pins = self.read_version_pins,
            .mutable_entries = @intCast(self.mutable.entryCount()),
            .mutable_bytes = estimateStateBytes(&self.mutable),
            .mutable_snapshot_clone_calls = self.mutable_snapshot_clone_calls,
            .mutable_snapshot_clone_bytes_total = self.mutable_snapshot_clone_bytes_total,
            .mutable_snapshot_clone_peak_bytes = self.mutable_snapshot_clone_peak_bytes,
            .mutable_snapshot_clone_by_reason = self.mutable_snapshot_clone_by_reason,
            .bulk_ingest_current_scan_clone_active_bytes = self.bulk_ingest_current_scan_clone_active_bytes,
            .bulk_ingest_current_scan_clone_peak_active_bytes = self.bulk_ingest_current_scan_clone_peak_active_bytes,
            .bulk_ingest_current_scan_clone_budget_denials = self.bulk_ingest_current_scan_clone_budget_denials,
            .bulk_ingest_current_scan_clone_oom_fallbacks = self.bulk_ingest_current_scan_clone_oom_fallbacks,
            .read_snapshot_mutable_rotations = self.read_snapshot_mutable_rotations,
            .read_snapshot_mutable_rotation_bytes_total = self.read_snapshot_mutable_rotation_bytes_total,
            .read_snapshot_mutable_rotation_peak_bytes = self.read_snapshot_mutable_rotation_peak_bytes,
            .immutable_memtables = @intCast(self.activeImmutableMemtableCount()),
            .retired_immutable_memtables = @intCast(self.retired_immutable_memtables.items.len),
            .immutable_pinned_generations = @intCast(self.immutable_memtable_pins.items.len),
            .total_runs = @intCast(self.runs.count()),
            .obsolete_paths = @intCast(self.obsolete_paths.count()),
            .current_manifest_bytes = self.current_manifest_bytes,
            .active_readers = (self.active_readers),
            .active_readers_by_kind = activeReaderKindStats(self.active_readers_by_kind),
            .active_bulk_ingest_batches = @intCast(self.active_bulk_ingest_batches),
            .soft_limit_l0_runs = @intCast(self.effectiveL0SoftLimitRuns()),
            .hard_limit_l0_runs = @intCast(self.effectiveL0HardLimitRuns()),
            .soft_limit_l0_bytes = self.options.l0_soft_limit_bytes,
            .hard_limit_l0_bytes = self.options.l0_hard_limit_bytes,
            .wal_soft_limit_segments = self.options.wal_soft_limit_segments,
            .wal_hard_limit_segments = self.options.wal_hard_limit_segments,
            .wal_soft_limit_bytes = self.options.wal_soft_limit_bytes,
            .wal_hard_limit_bytes = self.options.wal_hard_limit_bytes,
            .wal_checkpoint_pending = self.wal_checkpoint_pending,
            .wal_pressure_blocked = self.wal_pressure_blocked,
            .wal_checkpoint_retry_reason = self.wal_checkpoint_retry_reason,
            .wal_checkpoint_retry_attempts = self.wal_checkpoint_retry_attempts,
            .wal_checkpoint_retry_delay_ns = self.walCheckpointRetryRemainingNsLocked(),
            .active_immutable_logical_bytes = self.active_immutable_logical_bytes,
            .unpublished_wal_logical_bytes = self.unpublished_wal_logical_bytes,
            .unpublished_wal_max_batch_logical_bytes = self.unpublished_wal_max_batch_logical_bytes,
            .manifest_dirty = self.manifest_dirty,
            .obsolete_manifest_dirty = self.obsolete_manifest_dirty,
            .obsolete_delete_failures = self.obsolete_delete_failures,
            .obsolete_delete_retries = self.obsolete_delete_retries,
        };
        const obsolete_now_ns = self.nowNs();
        if (self.options.unpublished_outputs) |queue| {
            stats.unpublished_output_cleanup_pending = queue.pending.load(.acquire);
            stats.unpublished_output_cleanup_bytes = queue.bytes.load(.acquire);
        }
        stats.unpublished_output_cleanup_admission_failures = self.output_cleanup_admission_failures;
        var retired_ledger = self.retired_ledger_snapshots;
        while (retired_ledger) |snapshot| : (retired_ledger = snapshot.retired_next) stats.ledger_reclaim_pending +|= 1;
        stats.ledger_reclaim_slices = self.ledger_reclaim_slices;
        stats.ledger_reclaim_units = self.ledger_reclaim_units;
        stats.ledger_reclaim_max_slice_ns = self.ledger_reclaim_max_slice_ns;
        stats.memtable_reclaim_pending = self.memtable_reclaim_pending;
        stats.memtable_reclaim_slices = self.memtable_reclaim_slices;
        stats.memtable_reclaim_units = self.memtable_reclaim_units;
        stats.memtable_reclaim_max_slice_ns = self.memtable_reclaim_max_slice_ns;
        stats.tombstone_reconcile_rows = self.tombstone_reconcile_rows;
        stats.tombstone_reconcile_completed = self.tombstone_reconcile_completed;
        stats.tombstone_reconcile_failures = self.tombstone_reconcile_failures;
        stats.bulk_planning_jobs = @intFromBool(self.pending_bulk_plan != null);
        var obsolete_cursor = self.obsolete_paths.iterator();
        while (obsolete_cursor.next()) |obsolete| {
            // An open manifest independently pins the file even when its run
            // directory also owns a shared metadata pin. Attribute that case
            // to the manifest, not to a nonexistent active transaction.
            if (obsolete_path_refs.isRetained(obsolete.path)) {
                stats.obsolete_paths_pinned_by_versions +|= 1;
            } else if (run_snapshot_refs.isRetained(obsolete.path)) {
                stats.obsolete_paths_pinned_by_readers +|= 1;
                for (self.active_readers_by_kind, 0..) |active, kind_index| {
                    if (active != 0) stats.obsolete_paths_pinned_by_reader_kind[kind_index] +|= 1;
                }
            } else if (self.pathTrackedByActiveRunsLocked(obsolete.path) or self.obsoletePathPinnedByOpenVersion(obsolete.path)) {
                stats.obsolete_paths_pinned_by_versions +|= 1;
            } else if (obsolete.delete_after_ns > obsolete_now_ns) {
                stats.obsolete_paths_waiting_for_retry +|= 1;
            } else {
                stats.obsolete_paths_reclaimable +|= 1;
            }
        }
        for (self.activeImmutableMemtables()) |state| {
            stats.immutable_entries += @intCast(state.entryCount());
            stats.immutable_bytes += estimateStateBytes(state);
        }
        for (self.retired_immutable_memtables.items) |state| {
            stats.retired_immutable_entries +|= @intCast(state.entryCount());
            stats.retired_immutable_bytes +|= estimateStateBytes(state);
        }
        for (self.immutable_memtable_pins.items) |pin| {
            stats.immutable_pin_refs +|= @intCast(pin.readers);
        }

        var i: usize = 0;
        while (i < self.runs.count()) {
            const level = self.runs.at(i).*.level;
            const start = i;
            var level_bytes: u64 = 0;
            while (i < self.runs.count() and self.runs.at(i).*.level == level) : (i += 1) {
                const run = self.runs.at(i).*;
                level_bytes += run.size_bytes;
                stats.tombstone_entries +|= run.tombstone_count orelse 0;
                stats.unknown_tombstone_runs +|= @intFromBool(run.tombstone_count == null);
                stats.total_run_logical_entry_bytes +|= run.compression_stats.logical_entry_bytes;
                stats.total_run_physical_entry_bytes +|= run.compression_stats.physical_entry_bytes;
                stats.total_run_compressed_blocks +|= run.compression_stats.compressed_blocks;
                stats.total_run_raw_blocks +|= run.compression_stats.raw_blocks;
                stats.total_run_compression_codec_mask |= run.compression_stats.compression_codec_mask;
            }

            const level_len = i - start;
            stats.total_run_bytes += level_bytes;
            stats.max_level = @max(stats.max_level, level);
            if (level == 0) {
                stats.l0_runs = @intCast(level_len);
                stats.l0_bytes = level_bytes;
                stats.write_stall_l0_run_debt = self.l0RunDebtForHardLimit(level_len, self.effectiveL0HardLimitRuns());
                stats.write_stall_l0_byte_debt = self.l0ByteDebtForHardLimit(level_bytes, self.options.l0_hard_limit_bytes);
                if (level_len > self.options.compact_threshold_runs) {
                    stats.compactable_l0_runs = @intCast(level_len - self.options.compact_threshold_runs);
                }
                stats.overlapping_l0_runs = @intCast(self.largestL0OverlapRunCountLocked());
            } else {
                stats.lower_level_runs += @intCast(level_len);
                stats.lower_level_bytes += level_bytes;
                const target_runs = maintenanceLevelRunTarget(level, self.options.level_target_runs_base, self.options.level_target_runs_multiplier);
                if (level_len > target_runs) {
                    stats.level_overflow_runs += @intCast(level_len - target_runs);
                }
                const target_bytes = compaction_mod.levelByteTargetForTotals(self.runs.totalBytes(), self.runs.maxLevel(), level, self.options.level_target_bytes_base, self.options.level_target_bytes_multiplier);
                if (target_bytes > 0 and level_bytes > target_bytes) {
                    stats.level_overflow_bytes += level_bytes - target_bytes;
                }
            }
        }

        const scheduler_stats = self.compaction_scheduler.snapshotAt(platform_time.monotonicNs());
        stats.compaction_scheduler_active_jobs = scheduler_stats.active_jobs;
        stats.compaction_scheduler_in_flight_input_bytes = scheduler_stats.in_flight_input_bytes;
        stats.compaction_scheduler_active_oldest_age_ns = scheduler_stats.active_oldest_age_ns;
        stats.compaction_scheduler_grants = scheduler_stats.grants;
        stats.compaction_scheduler_completions = scheduler_stats.completions;
        stats.compaction_scheduler_denied_capacity = scheduler_stats.denied_capacity;
        stats.compaction_scheduler_denied_resource_pressure = scheduler_stats.denied_resource_pressure;
        stats.compaction_scheduler_oversized_grants = scheduler_stats.oversized_grants;
        stats.compaction_scheduler_oversized_skips = scheduler_stats.oversized_skips;
        stats.compaction_scheduler_remembered_candidates = scheduler_stats.remembered_candidates;
        stats.compaction_scheduler_remembered_retries = scheduler_stats.remembered_retries;
        stats.compaction_scheduler_remembered_hits = scheduler_stats.remembered_hits;
        stats.compaction_scheduler_remembered_stale = scheduler_stats.remembered_stale;
        stats.compaction_scheduler_conflict_denials = scheduler_stats.conflict_denials;
        if (self.remembered_compaction) |remembered| {
            stats.compaction_scheduler_remembered_pending = 1;
            stats.compaction_scheduler_remembered_pending_runs = @intCast(remembered.input_runs);
            stats.compaction_scheduler_remembered_pending_bytes = remembered.input_bytes;
        }
        for (self.pending_admissions) |pending| if (pending) |job| {
            if (!job.denied) continue;
            stats.compaction_scheduler_remembered_pending += 1;
            stats.compaction_scheduler_remembered_pending_runs +|= job.work.input_runs;
            stats.compaction_scheduler_remembered_pending_bytes +|= job.work.input_bytes;
        };
        stats.background_io_budget_bytes = self.options.background_io_budget_bytes;
        stats.background_io_reserved_bytes = self.background_io_reserved_bytes;
        stats.background_io_denied_jobs = self.background_io_denied_jobs;
        stats.background_io_oversized_jobs = self.background_io_oversized_jobs;
        stats.backend_lock_waits = self.backend_lock_waits.load(.monotonic);
        stats.backend_lock_wait_ns = self.backend_lock_wait_ns.load(.monotonic);
        stats.backend_lock_max_wait_ns = self.backend_lock_max_wait_ns.load(.monotonic);
        if (include_retention and self.options.wal_enabled and self.root_dir != null) {
            const wal_retention = self.cachedWalRetentionLocked() catch wal_mod.RetentionStats{};
            stats.wal_retained_segments = wal_retention.segments;
            stats.wal_retained_bytes = wal_retention.bytes;
            stats.wal_checkpoint_oldest_retained_segment = wal_retention.oldest_retained_segment;
            stats.wal_checkpoint_covered_through_segment = wal_retention.checkpoint_covered_through_segment;
            stats.wal_checkpoint_current_segment = wal_retention.current_segment;
            const over_soft = self.walRetentionOverSoftLimit(wal_retention);
            const over_hard = self.walRetentionOverHardLimit(wal_retention);
            stats.wal_checkpoint_pending = stats.wal_checkpoint_pending or over_soft;
            stats.wal_pressure_blocked = stats.wal_pressure_blocked or over_hard;
            if (stats.wal_checkpoint_pending and stats.wal_checkpoint_retry_reason == .none) {
                stats.wal_checkpoint_retry_reason = if (over_hard) .hard_pressure else .soft_pressure;
            }
            if (wal_retention.current_segment > wal_retention.oldest_retained_segment) {
                stats.wal_checkpoint_lag_segments = wal_retention.current_segment - wal_retention.oldest_retained_segment;
            }
            const replay_retention = self.cachedWalReplayRetentionLocked() catch wal_mod.RetentionStats{};
            stats.wal_retained_segments += replay_retention.segments;
            stats.wal_retained_bytes += replay_retention.bytes;
            stats.wal_replay_retained_segments = replay_retention.segments;
            stats.wal_replay_retained_bytes = replay_retention.bytes;
            stats.wal_replay_current_segment = replay_retention.current_segment;
            self.syncTrackedWalRetentionUsageLocked(stats.wal_retained_bytes);
        }
        self.syncTrackedInMemoryStateUsageLocked(stats);
        return stats;
    }

    pub fn recordBackendLockWait(self: *Backend, wait_ns: u64) void {
        _ = self.backend_lock_waits.fetchAdd(1, .monotonic);
        _ = self.backend_lock_wait_ns.fetchAdd(wait_ns, .monotonic);
        atomicMaxCounter(&self.backend_lock_max_wait_ns, wait_ns);
    }

    pub fn snapshotCacheStats(self: *const Backend) ?cache_mod.Stats {
        const cache = self.options.cache orelse return null;
        return cache.snapshotStats();
    }

    pub fn snapshotNativeStorageStats(self: *const Backend) ?storage_io.NativeStorageStats {
        const owner = self.storage_owner orelse return null;
        return owner.snapshotStats();
    }

    /// Retains the internally-created native storage after this LSM backend is
    /// closed. Backends using a caller-owned Storage return null; that caller
    /// already owns the required lifetime.
    pub fn acquireNativeStorageLease(self: *Backend) !?storage_io.NativeStorage.Lease {
        const owner = self.storage_owner orelse return null;
        return try owner.acquireLease();
    }

    pub fn maintenanceDebtHint(self: *const Backend) u64 {
        return self.cached_maintenance_hint.load(.monotonic);
    }

    pub fn notePotentialMaintenanceDebt(self: *Backend) void {
        self.cached_maintenance_hint.store(1, .release);
        if (self.options.maintenance_waker != null) {
            self.wakeMaintenanceWorker();
            return;
        }
        if (!self.mu.tryLock()) return;
        defer self.mu.unlock();
        self.scheduleMaintenanceJobIfNeededLocked();
    }

    pub fn notePotentialMaintenanceDebtLocked(self: *Backend) void {
        self.cached_maintenance_hint.store(1, .release);
        if (self.options.maintenance_waker != null) {
            self.wakeMaintenanceWorker();
            return;
        }
        self.scheduleMaintenanceJobIfNeededLocked();
    }

    pub fn noteWriteMutationLocked(self: *Backend) void {
        if (self.options.mutable_idle_flush_after_ns > 0 and
            self.mutable.entryCount() > 0 and
            !self.options.backend.read_only)
        {
            const now_ns = self.nowNs();
            if (self.mutable_idle_flush_max_deadline_ns == 0 and
                self.options.mutable_idle_flush_max_age_ns > 0)
            {
                self.mutable_idle_flush_max_deadline_ns = now_ns +| self.options.mutable_idle_flush_max_age_ns;
            }

            const idle_eligible = self.options.mutable_idle_flush_min_bytes == 0 or
                self.mutable.estimatedLogicalBytes() >= self.options.mutable_idle_flush_min_bytes;
            const idle_deadline = if (idle_eligible)
                now_ns +| self.options.mutable_idle_flush_after_ns
            else
                std.math.maxInt(u64);
            self.mutable_idle_flush_deadline_ns = if (self.mutable_idle_flush_max_deadline_ns > 0)
                @min(idle_deadline, self.mutable_idle_flush_max_deadline_ns)
            else if (idle_eligible)
                idle_deadline
            else
                0;
        } else {
            self.mutable_idle_flush_deadline_ns = 0;
            self.mutable_idle_flush_max_deadline_ns = 0;
        }
        self.notePotentialMaintenanceDebtLocked();
    }

    /// Apply the mutable-table idle policy to the complete, WAL-backed epochs
    /// retained for a windowed flush. Full windows publish immediately; a
    /// partial final window remains query-visible in memory until write
    /// quiescence, while the maximum-age deadline prevents a quiet table from
    /// retaining that memory and WAL indefinitely.
    fn noteImmutableWriteMutationLocked(self: *Backend) void {
        if (self.options.mutable_idle_flush_after_ns > 0 and
            self.activeImmutableMemtableCount() > 0 and
            !self.options.backend.read_only)
        {
            const now_ns = self.nowNs();
            if (self.immutable_idle_flush_max_deadline_ns == 0 and
                self.options.mutable_idle_flush_max_age_ns > 0)
            {
                self.immutable_idle_flush_max_deadline_ns = now_ns +| self.options.mutable_idle_flush_max_age_ns;
            }

            const idle_eligible = self.options.mutable_idle_flush_min_bytes == 0 or
                self.activeImmutableMemtableBytes() >= self.options.mutable_idle_flush_min_bytes;
            const idle_deadline = if (idle_eligible)
                now_ns +| self.options.mutable_idle_flush_after_ns
            else
                std.math.maxInt(u64);
            self.immutable_idle_flush_deadline_ns = if (self.immutable_idle_flush_max_deadline_ns > 0)
                @min(idle_deadline, self.immutable_idle_flush_max_deadline_ns)
            else if (idle_eligible)
                idle_deadline
            else
                0;
        } else {
            self.clearImmutableIdleFlushDeadlineIfEmptyLocked();
        }
    }

    fn clearImmutableIdleFlushDeadlineIfEmptyLocked(self: *Backend) void {
        if (self.activeImmutableMemtableCount() != 0) return;
        self.immutable_idle_flush_deadline_ns = 0;
        self.immutable_idle_flush_max_deadline_ns = 0;
    }

    /// WAL replay proves this mutable state was already dirty before this
    /// process started. Its original monotonic timestamp cannot be recovered,
    /// so granting it a fresh maximum-age interval on every restart could
    /// postpone checkpointing forever. Make recovered state immediately
    /// eligible; the maintenance worker still performs the normal atomic
    /// run/manifest/WAL checkpoint sequence.
    pub fn noteRecoveredWriteMutationLocked(self: *Backend) void {
        if (self.options.mutable_idle_flush_after_ns > 0 and
            self.mutable.entryCount() > 0 and
            !self.options.backend.read_only)
        {
            const due_ns = @max(self.nowNs(), 1);
            self.mutable_idle_flush_deadline_ns = due_ns;
            self.mutable_idle_flush_max_deadline_ns = due_ns;
        } else {
            self.mutable_idle_flush_deadline_ns = 0;
            self.mutable_idle_flush_max_deadline_ns = 0;
        }
        self.notePotentialMaintenanceDebtLocked();
    }

    fn wakeMaintenanceWorker(self: *Backend) void {
        if (self.options.maintenance_waker) |waker| waker.wake();
    }

    pub fn refreshMaintenanceDebtHint(self: *Backend) void {
        const locked = runtime_mod.lockBackend(Backend, self);
        defer runtime_mod.unlockBackend(Backend, self, locked);
        _ = self.refreshCachedMaintenanceHintLocked();
    }

    pub fn maintenanceScore(self: *const Backend) u64 {
        const mutable: *Backend = @constCast(self);
        const locked = runtime_mod.lockBackend(Backend, mutable);
        defer runtime_mod.unlockBackend(Backend, mutable, locked);
        return mutable.maintenanceScoreLocked();
    }

    pub fn maintenanceScoreBestEffort(self: *Backend) ?u64 {
        if (!self.mu.tryLock()) return null;
        defer self.mu.unlock();
        return self.maintenanceScoreLocked();
    }

    fn largestL0OverlapRunCountLocked(self: *Backend) usize {
        const threshold = self.options.l0_overlap_compact_threshold_runs;
        if (threshold == 0) return 0;
        // Above the soft limit, normal L0 pressure already schedules
        // compaction. Exact overlap scoring is O(n^2) and runs under `mu`, so
        // performing it during overload can block point and batch reads for
        // seconds. Zero here means "not independently scored"; L0 run/byte
        // pressure remains fully represented by the surrounding metrics.
        const soft_limit = self.effectiveL0SoftLimitRuns();
        if (soft_limit == 0) return 0;
        const limit = @min(soft_limit, compaction_mod.max_exact_l0_overlap_runs);
        const l0_count = self.overlapScoringL0Count(limit);
        if (l0_count > limit) return 0;
        var scratch: [compaction_mod.max_exact_l0_overlap_runs]Run = undefined;
        const l0_runs = scratch[0..l0_count];
        for (l0_runs, 0..) |*run, rank| run.* = self.runs.at(rank).*;
        if (self.l0_overlap_cache.lookup(l0_runs, threshold)) |cached| return cached;
        const result = compaction_mod.largestL0OverlapRunCount(l0_runs, threshold);
        self.l0_overlap_cache.store(l0_runs, threshold, result);
        return result;
    }

    // Do not walk an overloaded L0 merely to decide not to score it. Ordinary
    // publications maintain the aggregate; cold/test roots need at most
    // limit + 1 probes, independent of the size of the backlog.
    fn overlapScoringL0Count(self: *const Backend, limit: usize) usize {
        if (!self.run_directory_dirty) if (self.run_directory) |directory| return directory.levelStats(0).count;
        var count: usize = 0;
        while (count < self.runs.count() and count <= limit and self.runs.at(count).level == 0) : (count += 1) {}
        return count;
    }

    fn maintenanceScoreLocked(self: *Backend) u64 {
        var score: u64 = 0;
        if (@import("lsm_backend/memtable_reclamation.zig").pending(self)) score +|= 1;
        if (@import("lsm_backend/read_metadata_reclamation.zig").pending(self)) score +|= 1;
        if (self.retired_ledger_snapshots != null and !self.ledger_reclaim_in_flight) score +|= 1;
        if ((self.outputCleanupDelayLocked() orelse 1) == 0) score +|= 1;
        if (self.pending_bulk_plan != null or self.retired_bulk_plans != null) score +|= 1;
        if (self.tombstoneReconcileDelayLocked()) |delay| if (delay == 0) {
            score +|= 1;
        };
        if (self.pending_directory_closure != null or self.pending_l0_directory_closure != null or self.retired_closures != null) score += 1;
        if (self.retired_admissions != null) score += 1;
        for (self.pending_admissions) |pending| if (pending != null) {
            score += 1;
        };
        if (self.pending_gc != null or self.retired_gc != null or self.directory_reclaimer != null or self.retired_run_directories != null) score +|= 1;
        if (self.retired_run_stores != null or self.store_reclaimer != null) score +|= 1;
        if (self.obsolete_run_count != 0 and (self.obsolete_run_drain_remaining != 0 or self.obsolete_run_pin_epoch != file_pin_release_epoch.load(.acquire))) score +|= 1;
        if (self.manifest_journal.checkpointDue() and self.manifest_journal.sequence != null) score += 1;
        const directory = if (!self.run_directory_dirty) self.run_directory else null;

        const soft_limit_l0_runs = self.effectiveL0SoftLimitRuns();
        const hard_limit_l0_runs = self.effectiveL0HardLimitRuns();
        const tiered_l0 = self.options.run_partition_key == null and self.options.bulk_ingest_tiered_l0_fan_in >= 2;
        const has_l0_tier = tiered_l0 and
            compaction_mod.bulkDirectoryPlanningDue(self, .{ .fan_in = self.options.bulk_ingest_tiered_l0_fan_in, .max_bytes = self.options.max_compaction_input_bytes });
        if (hard_limit_l0_runs > 0) {
            const l0_runs = if (directory) |root| root.levelStats(0).count else countLevelRuns(&self.runs, 0);
            if (l0_runs > hard_limit_l0_runs) {
                score +|= (l0_runs - hard_limit_l0_runs) * 1_000_000;
            } else if (l0_runs > soft_limit_l0_runs and (!tiered_l0 or has_l0_tier)) {
                score +|= (l0_runs - soft_limit_l0_runs) * 10_000;
            }
            if (!tiered_l0 and l0_runs > self.options.compact_threshold_runs) {
                score +|= (l0_runs - self.options.compact_threshold_runs) * 1_000;
            }
            if (!tiered_l0) score +|= self.largestL0OverlapRunCountLocked() * 2_000;
        }
        if (self.l0SoftPressureLocked() and has_l0_tier) {
            score +|= 2_500;
        }

        var l0_bytes: u64 = 0;
        var level_overflow_runs: u64 = 0;
        var level_overflow_bytes: u64 = 0;
        var has_tombstones = false;
        var i: usize = 0;
        while (i < if (directory) |root| root.levelCount() else self.runs.count()) {
            const aggregate = if (directory) |root| blk: {
                const level = root.levelAt(i);
                i += 1;
                break :blk level;
            } else blk: {
                var level = run_directory_mod.LevelAggregate{ .level = self.runs.at(i).*.level };
                while (i < self.runs.count() and self.runs.at(i).*.level == level.level) : (i += 1) {
                    level.count += 1;
                    level.bytes += self.runs.at(i).*.size_bytes;
                    level.tombstone_runs += @intFromBool((self.runs.at(i).*.tombstone_count orelse 0) != 0);
                }
                break :blk level;
            };
            const level = aggregate.level;
            const level_bytes = aggregate.bytes;
            const level_len = aggregate.count;
            has_tombstones = has_tombstones or aggregate.tombstone_runs != 0;
            if (level == 0) {
                l0_bytes = level_bytes;
                continue;
            }

            const target_runs = maintenanceLevelRunTarget(level, self.options.level_target_runs_base, self.options.level_target_runs_multiplier);
            if (level_len > target_runs) {
                level_overflow_runs +|= @intCast(level_len - target_runs);
            }
            const target_bytes = if (directory) |root|
                compaction_mod.levelByteTargetForTotals(root.total_run_bytes, root.maxLevel(), level, self.options.level_target_bytes_base, self.options.level_target_bytes_multiplier)
            else
                compaction_mod.levelByteTargetForTotals(self.runs.totalBytes(), self.runs.maxLevel(), level, self.options.level_target_bytes_base, self.options.level_target_bytes_multiplier);
            if (target_bytes > 0 and level_bytes > target_bytes) {
                level_overflow_bytes +|= level_bytes - target_bytes;
            }
        }

        if (self.options.l0_hard_limit_bytes > 0 and l0_bytes > self.options.l0_hard_limit_bytes) {
            score +|= (l0_bytes - self.options.l0_hard_limit_bytes) / 1024;
        } else if (self.options.l0_soft_limit_bytes > 0 and
            l0_bytes > self.options.l0_soft_limit_bytes and
            (!tiered_l0 or has_l0_tier))
        {
            score +|= (l0_bytes - self.options.l0_soft_limit_bytes) / (16 * 1024);
        }

        const immutable_memtables = self.activeImmutableMemtableCount();
        score +|= @as(u64, @intCast(immutable_memtables)) * 5_000;
        for (self.activeImmutableMemtables()) |state| {
            score +|= estimateStateBytes(state) / (16 * 1024);
        }

        score +|= level_overflow_runs * 500;
        score +|= level_overflow_bytes / (64 * 1024);
        if (has_tombstones and compaction_mod.hasTombstoneGcDebt(self)) score +|= 1;
        score +|= self.walRetentionPressureScoreLocked();
        if (self.manifest_dirty or self.obsolete_manifest_dirty or self.hasReclaimableObsoletePathsLocked()) score +|= 1;
        return score;
    }

    fn refreshCachedMaintenanceHintLocked(self: *Backend) u64 {
        const score = self.maintenanceScoreLocked();
        self.cached_maintenance_hint.store(score, .release);
        return score;
    }

    fn syncTrackedInMemoryStateUsageLocked(self: *Backend, stats: MaintenanceStats) void {
        _ = stats;
        const manager = self.options.resource_manager orelse return;
        manager.observeUsage(
            .lsm_in_memory_state,
            &self.tracked_in_memory_state_bytes,
            self.estimateInMemoryStateBytesLocked(),
        );
    }

    pub fn syncTrackedInMemoryStateUsageCurrentLocked(self: *Backend) void {
        const manager = self.options.resource_manager orelse return;
        manager.observeUsage(
            .lsm_in_memory_state,
            &self.tracked_in_memory_state_bytes,
            self.estimateInMemoryStateBytesLocked(),
        );
    }

    fn syncTrackedWalRetentionUsageCurrentLocked(self: *Backend) void {
        const manager = self.options.resource_manager orelse return;
        if (!self.options.wal_enabled or self.root_dir == null) return;
        const retention = self.cachedWalRetentionLocked() catch wal_mod.RetentionStats{};
        const replay_retention = self.cachedWalReplayRetentionLocked() catch wal_mod.RetentionStats{};
        manager.observeUsage(
            .lsm_wal_retention,
            &self.tracked_wal_retention_bytes,
            retention.bytes +| replay_retention.bytes,
        );
    }

    fn syncTrackedWalRetentionUsageLocked(self: *Backend, bytes: u64) void {
        const manager = self.options.resource_manager orelse return;
        manager.observeUsage(.lsm_wal_retention, &self.tracked_wal_retention_bytes, bytes);
    }

    fn estimateInMemoryStateBytesLocked(self: *const Backend) u64 {
        return self.estimateInMemoryStateBytesWithCandidateLocked(null);
    }

    fn estimateInMemoryStateBytesWithCandidateLocked(self: *const Backend, candidate: ?*const ActiveMemTable) u64 {
        const pass = state_mod.memory_account.nextPass();
        var bytes = self.mutable.accountedMemoryBytes(pass);
        // Tickets already own builder-slice reservations. Only the queue
        // header belongs to this observer; charging tickets here duplicates
        // their contribution to the resource manager's aggregate budget.
        if (self.options.unpublished_outputs) |queue| bytes +|= queue.observedMemoryBytes();
        var ledger_reclamation = self.active_ledger_reclamations;
        while (ledger_reclamation) |job| : (ledger_reclamation = job.next) bytes +|= job.memoryBytes(pass);
        var ledger_snapshot = self.ledger_snapshots;
        while (ledger_snapshot) |snapshot| : (ledger_snapshot = snapshot.active_next) bytes +|= snapshot.memoryBytes(pass);
        var publication = self.active_compaction_publications;
        while (publication) |job| : (publication = job.next) bytes +|= job.accountedMemoryBytes(pass);
        bytes +|= self.runs.memoryBytes(pass);
        var retired_store = self.retired_run_stores;
        while (retired_store) |store| : (retired_store = store.retired_next) bytes +|= @sizeOf(RunStore) + store.memoryBytes(pass);
        if (self.store_reclaimer) |*job| bytes +|= @sizeOf(RunStore) + job.store.memoryBytes(pass);
        if (self.run_directory) |directory| bytes +|= directory.accountedMemoryBytes(pass);
        if (self.manifest_directory) |directory| bytes +|= directory.accountedMemoryBytes(pass);
        if (self.manifest_checkpoint_directory) |directory| bytes +|= directory.accountedMemoryBytes(pass);
        if (self.pending_directory_closure) |pending| bytes +|= pending.directory.accountedMemoryBytes(pass);
        if (self.pending_l0_directory_closure) |pending| bytes +|= pending.directory.accountedMemoryBytes(pass);
        for (self.pending_admissions) |pending| if (pending) |job| {
            bytes +|= job.accountedMemoryBytes(pass);
        };
        var retired_admission = self.retired_admissions;
        while (retired_admission) |pending| : (retired_admission = pending.retired_next) bytes +|= pending.accountedMemoryBytes(pass);
        var active_bulk = self.active_bulk_plans;
        while (active_bulk) |pending| : (active_bulk = pending.active_next) bytes +|= pending.accountedMemoryBytes(pass);
        if (self.pending_tombstone_reconcile) |pending| bytes +|= pending.account.chargeOnce(pass);
        var retired_bulk = self.retired_bulk_plans;
        while (retired_bulk) |pending| : (retired_bulk = pending.retired_next) bytes +|= pending.accountedMemoryBytes(pass);
        var retired_closure = self.retired_closures;
        while (retired_closure) |pending| : (retired_closure = pending.retired_next) bytes +|= pending.directory.accountedMemoryBytes(pass);
        if (self.pending_gc) |pending| bytes +|= pending.accountedMemoryBytes(pass);
        var retired_gc = self.retired_gc;
        while (retired_gc) |pending| : (retired_gc = pending.retired_next) bytes +|= pending.accountedMemoryBytes(pass);
        bytes +|= self.manifest_journal.obsolete.memoryBytes(pass);
        bytes +|= self.obsolete_paths.memoryBytes(pass);
        if (self.obsolete_reclaim_after) |path| bytes +|= path.len;
        var live_version = self.live_read_versions;
        while (live_version) |version| : (live_version = version.live_next) bytes +|= version.accountedMemoryBytes(pass);
        bytes +|= runMetadataMemoryBytes(self.retired_run_directories, self.retired_read_versions, pass);
        if (self.directory_reclaimer) |*job| bytes +|= job.directory.accountedMemoryBytes(pass);
        if (self.domain_index) |index| bytes +|= index.memoryBytes();
        var retired_domain = self.retired_domain_indexes;
        while (retired_domain) |index| : (retired_domain = index.retired_next) bytes +|= index.memoryBytes();
        bytes +|= runMetadataMemoryBytes(null, self.retired_projection_versions, pass);
        if (self.read_metadata_reclaimer) |*job| bytes +|= job.memoryBytes(pass);
        for (self.activeImmutableMemtables()) |state| {
            bytes +|= state.accountedMemoryBytes(pass);
        }
        for (self.retired_immutable_memtables.items) |state| {
            bytes +|= state.accountedMemoryBytes(pass);
        }
        bytes +|= self.bulk_snapshot_unshared_bytes;
        var accounts = self.bulk_snapshot_accounts.keyIterator();
        while (accounts.next()) |account| bytes +|= account.*.chargeOnce(pass);
        if (self.mutable_read_snapshot) |snapshot| bytes +|= snapshot.accountedMemoryBytes(pass);
        for (self.retired_mutable_snapshots.items) |snapshot| bytes +|= snapshot.accountedMemoryBytes(pass);
        if (candidate) |prepared| bytes +|= prepared.accountedMemoryBytes(pass);
        var retired = self.retired_memory_head;
        while (retired) |state| : (retired = state.retired_next) bytes +|= @sizeOf(State) +| state.accountedMemoryBytes(pass);
        if (self.memtable_reclaimer) |*job| bytes +|= job.memoryBytes(pass);
        var reclaiming = self.reclaiming_memory;
        while (reclaiming) |batch| : (reclaiming = batch.next) {
            bytes +|= runMetadataMemoryBytes(null, batch.versions, pass);
        }
        return bytes;
    }

    fn runMetadataMemoryBytes(directories: ?*RunDirectory, versions: ?*runtime_mod.ReadVersion, pass: u64) u64 {
        var bytes: u64 = 0;
        var directory = directories;
        while (directory) |item| : (directory = item.retired_next) bytes +|= item.accountedMemoryBytes(pass);
        var version = versions;
        while (version) |item| : (version = item.retired_next) bytes +|= item.accountedMemoryBytes(pass);
        return bytes;
    }

    fn mutableReadSnapshotBytesLocked(self: *const Backend) u64 {
        var bytes: u64 = 0;
        if (self.mutable_read_snapshot) |snapshot| {
            bytes +|= estimateStateBytes(snapshot);
        }
        for (self.retired_mutable_snapshots.items) |snapshot| {
            bytes +|= estimateStateBytes(snapshot);
        }
        return bytes;
    }

    pub fn releaseTrackedResourceUsage(self: *Backend) void {
        const manager = self.options.resource_manager orelse return;
        manager.observeUsage(.lsm_in_memory_state, &self.tracked_in_memory_state_bytes, 0);
        manager.observeUsage(.lsm_wal_retention, &self.tracked_wal_retention_bytes, 0);
        manager.observeUsage(.lsm_recovery_working_set, &self.tracked_recovery_working_set_bytes, 0);
    }

    pub fn releaseObsoleteLedgerLocked(self: *Backend, ledger: *repository_mod.ObsoleteLedger) void {
        @import("lsm_backend/ledger_reclamation.zig").drainLocked(self, ledger);
    }

    pub fn drainRetiredLedgers(self: *Backend) void {
        _ = runtime_mod.lockBackend(Backend, self);
        while (self.retired_ledger_snapshots != null) @import("lsm_backend/ledger_reclamation.zig").reclaimSliceLocked(self);
        std.debug.assert(self.ledger_snapshots == null);
        self.mu.unlock();
    }

    pub fn drainRetiredMemtables(self: *Backend) void {
        @import("lsm_backend/memtable_reclamation.zig").drain(self);
    }

    pub fn acquireCompactionGrant(self: *Backend, work: anytype) ?compaction_scheduler_mod.Grant {
        const io_bytes = if (@hasField(@TypeOf(work), "io_bytes")) work.io_bytes else work.input_bytes;
        if (!self.canReserveMaintenanceIoBudget(io_bytes)) return null;
        var scheduler_work = compaction_scheduler_mod.Work{
            .score = work.score,
            .input_runs = work.input_runs,
            .input_bytes = work.input_bytes,
        };
        if (@hasField(@TypeOf(work), "run_ids")) {
            scheduler_work.run_ids = work.run_ids;
        }
        if (@hasField(@TypeOf(work), "run_id_index")) scheduler_work.run_id_index = work.run_id_index;
        if (@hasField(@TypeOf(work), "key_range")) {
            scheduler_work.key_range = work.key_range;
        }
        const grant = self.compaction_scheduler.tryAcquireAt(scheduler_work, self.options.resource_manager, platform_time.monotonicNs()) orelse return null;
        self.reserveMaintenanceIoBudgetAssumeAdmitted(io_bytes);
        return grant;
    }

    fn canReserveMaintenanceIoBudget(self: *Backend, io_bytes: u64) bool {
        const remaining = self.maintenance_io_budget_remaining orelse return true;
        if (io_bytes == 0 or io_bytes <= remaining) return true;
        const budget = self.options.background_io_budget_bytes;
        if (self.options.background_io_allow_oversized_single_job and remaining == budget) return true;
        self.background_io_denied_jobs +|= 1;
        return false;
    }

    fn reserveMaintenanceIoBudgetAssumeAdmitted(self: *Backend, io_bytes: u64) void {
        if (io_bytes == 0) return;
        const remaining = self.maintenance_io_budget_remaining orelse return;
        if (io_bytes <= remaining) {
            self.maintenance_io_budget_remaining = remaining - io_bytes;
            self.background_io_reserved_bytes +|= io_bytes;
            return;
        }
        self.maintenance_io_budget_remaining = 0;
        self.background_io_reserved_bytes +|= io_bytes;
        self.background_io_oversized_jobs +|= 1;
    }

    pub fn tryReserveMaintenanceIoBudget(self: *Backend, io_bytes: u64) bool {
        if (!self.canReserveMaintenanceIoBudget(io_bytes)) return false;
        self.reserveMaintenanceIoBudgetAssumeAdmitted(io_bytes);
        return true;
    }

    pub fn runMaintenanceStep(self: *Backend) !bool {
        const locked = runtime_mod.lockBackend(Backend, self);
        defer runtime_mod.unlockBackend(Backend, self, locked);
        return try self.runMaintenanceStepLocked(false);
    }

    /// An explicitly requested rewrite must make progress under sustained
    /// query traffic. It still uses ordinary I/O/memory admission and yields
    /// inside streaming work; only the optional idle-grace deferral is bypassed.
    pub fn runValueReclamationStep(self: *Backend) !bool {
        const locked = runtime_mod.lockBackend(Backend, self);
        defer runtime_mod.unlockBackend(Backend, self, locked);
        return try self.runMaintenanceStepLocked(true);
    }

    pub fn runMaintenanceStepBestEffort(self: *Backend) !bool {
        if (!self.mu.tryLock()) return false;
        defer self.unlockWithReclamation();
        return try self.runMaintenanceStepLocked(false);
    }

    pub fn makeWalCheckpointRetryDueForTest(self: *Backend) void {
        if (!builtin.is_test) return;
        const locked = runtime_mod.lockBackend(Backend, self);
        defer runtime_mod.unlockBackend(Backend, self, locked);
        self.wal_checkpoint_retry_deadline_ns = 0;
        self.last_wal_retention_enforce_ns = 0;
    }

    fn runMaintenanceStepLocked(self: *Backend, required_gc: bool) !bool {
        // Cleanup is safe even after a durability fence or under pressure.
        // The unlock path executes one bounded FIFO reclamation turn.
        if (self.retired_ledger_snapshots != null and !self.ledger_reclaim_in_flight) return true;
        if (@import("lsm_backend/memtable_reclamation.zig").pending(self)) return true;
        if (@import("lsm_backend/read_metadata_reclamation.zig").pending(self)) return true;
        if (!self.directory_reclaim_in_flight and (self.directory_reclaimer != null or self.retired_run_directories != null)) return true;
        if (self.manifest_recovery_required) return false;
        const reclaim_visits_before = self.obsolete_reclaim_visits;
        const planning_slices_before = self.directory_planning_slices;
        if (self.options.backend.read_only) return false;
        if ((self.outputCleanupDelayLocked() orelse 1) == 0) {
            const progressed = self.drainOutputCleanupSliceLocked() catch |err| switch (err) {
                error.OutOfMemory, error.ResourceBudgetExceeded => return false,
                else => return err,
            };
            if (progressed) try self.persistManifestLocked();
            return progressed;
        }
        // Admission pressure governs new work, not the lifetime of an owned
        // continuation. Retire obsolete jobs even while foreground work owns
        // the I/O lane; unlock reclamation drains their pins in bounded slices.
        const bulk_retired = self.retireUnneededBulkPlanLocked();
        compaction_mod.retireObsoleteAdmissions(self);
        if (!self.manifest_checkpoint_build_in_flight and self.manifest_journal.sequence != null and self.manifest_journal.checkpointDue()) {
            return try self.manifest_journal.runCheckpoint(self);
        }
        if (self.wal_checkpoint_pending and self.walCheckpointRetryDueLocked()) {
            if (try self.runWalPressureMaintenanceStepLocked()) return true;
        }
        self.maintenance_io_budget_remaining = if (self.options.background_io_budget_bytes > 0)
            self.options.background_io_budget_bytes
        else
            null;
        defer self.maintenance_io_budget_remaining = null;
        // Reconciliation has its own fair lane. An unknown SST never means
        // "zero deletes", and a large old run cannot monopolize maintenance.
        self.tombstone_reconcile_turn +%= 1;
        if (self.tombstone_reconcile_turn % 2 == 1 and !self.tombstone_reconcile_in_flight and
            (self.tombstoneReconcileDelayLocked() orelse 1) == 0)
        {
            return try compaction_mod.reconcileTombstonesStep(self);
        }
        // Ordinary leveled compaction remains deferred during bulk ingest, but
        // a pressured sorted-publication lane may stream one size-tier merge.
        // This prevents the import from reaching hard L0 pressure and then
        // repeatedly rewriting its entire overlapping lower-level base.
        if (self.bulkIngestActive()) {
            if (!self.bulkTieredL0MaintenanceDueLocked() or self.optionalMaintenanceDeferredLocked())
                return bulk_retired or (self.tombstoneReconcileDelayLocked() orelse 1) == 0;
            const compacted = try compaction_mod.compactBulkL0TierScheduledBeforeSequence(
                Backend,
                self,
                self.options.bulk_ingest_tiered_l0_fan_in,
                self.maintenanceScoreLocked(),
                self.bulk_ingest_window_first_sequence,
            );
            if (compacted and self.root_dir != null and
                (self.manifest_dirty or self.obsolete_manifest_dirty or self.hasReclaimableObsoletePathsLocked()))
            {
                try self.persistManifestLocked();
            }
            _ = self.refreshCachedMaintenanceHintLocked();
            return compacted;
        }
        const before_compactions = self.compaction_stats.compactions;
        const before_manifest_writes = self.write_stats.manifest_writes;
        const before_obsolete_paths = self.obsolete_paths.count();

        if (self.root_dir != null and self.hasReclaimableObsoletePathsLocked()) {
            try self.persistManifestLocked();
            _ = self.refreshCachedMaintenanceHintLocked();
            return self.write_stats.manifest_writes != before_manifest_writes or
                self.obsolete_paths.count() != before_obsolete_paths or
                self.obsolete_reclaim_visits != reclaim_visits_before;
        }

        const mutable_idle_flush_required = self.shouldFlushMutableForIdleLocked();
        const mutable_size_flush_required = self.shouldFlushMutable();
        const mutable_wal_flush_required = try self.shouldFlushMutableForWalPressureLocked();
        const mutable_flush_required = mutable_idle_flush_required or
            mutable_size_flush_required or
            mutable_wal_flush_required;
        const immutable_flush_required = self.shouldFlushImmutableForIdleLocked();
        if (mutable_flush_required) {
            try self.rotateMutableToImmutable();
        }
        if (self.activeImmutableMemtableCount() > 0) {
            // A size boundary ends one mutable generation, not the configured
            // durable publication window. Keep that WAL-backed epoch visible
            // in the immutable queue so adjacent generations can share one
            // sorted run build. Idle and WAL pressure remain explicit durable
            // boundaries, and disabling windowing preserves the legacy
            // one-generation-per-flush behavior.
            const force_partial_window = self.options.immutable_flush_window_bytes == 0 or
                mutable_idle_flush_required or
                mutable_wal_flush_required or
                immutable_flush_required;
            _ = try self.flushImmutableMemtableWindow(force_partial_window);
        } else {
            const soft_l0_runs = self.effectiveL0SoftLimitRuns();
            const score = self.maintenanceScoreLocked();
            // Compare L0 pressure against every lower level even when L0 is
            // above its soft bound. The old L0-only branch bypassed normalized
            // pressure selection, so a 3.2x L0 backlog rewrote an 8.5x-overfull
            // L1 before L1 could be promoted. Use the soft L0 bound as the
            // pressure denominator while retaining overlap-triggered L0 work.
            const defer_soft_compaction = !required_gc and self.optionalMaintenanceDeferredLocked();
            if (!defer_soft_compaction) {
                self.gc_maintenance_turn +%= 1;
                var compacted = self.pending_directory_closure == null and self.pending_l0_directory_closure == null and (required_gc or self.gc_maintenance_turn % 8 == 0) and (compaction_mod.nextTombstoneGcDelay(self) orelse 1) == 0 and
                    try compaction_mod.compactTombstonesScheduled(Backend, self, score);
                if (!compacted) {
                    compacted = if (self.l0SoftPressureLocked() and self.options.bulk_ingest_tiered_l0_fan_in >= 2)
                        try compaction_mod.compactBulkL0TierScheduled(
                            Backend,
                            self,
                            self.options.bulk_ingest_tiered_l0_fan_in,
                            score,
                        )
                    else
                        false;
                    if (!compacted) {
                        const tier_owns_soft_l0 = self.options.bulk_ingest_tiered_l0_fan_in >= 2 and
                            !self.l0HardPressureLocked();
                        if (tier_owns_soft_l0) {
                            compacted = try compaction_mod.maybeCompactLowerLevelsScheduled(Backend, self, score);
                        } else {
                            compacted = try compaction_mod.maybeCompactRunsScheduledWithL0Limit(
                                Backend,
                                self,
                                if (soft_l0_runs > 0) soft_l0_runs else self.options.compact_threshold_runs,
                                score,
                            );
                        }
                    }
                }
                if (!compacted and self.pending_directory_closure == null and self.pending_l0_directory_closure == null)
                    _ = try compaction_mod.compactTombstonesScheduled(Backend, self, score);
            }
        }
        // Hard L0/WAL bounds remain authoritative even while latency-sensitive
        // derived replay is active. This path may compact or reject writes when
        // debt crosses those limits; only optional soft compaction is deferred.
        try self.enforceWritePressure();
        if (self.root_dir != null and (self.manifest_dirty or self.obsolete_manifest_dirty or self.hasReclaimableObsoletePathsLocked())) {
            try self.persistManifestLocked();
        }

        _ = self.refreshCachedMaintenanceHintLocked();

        return bulk_retired or self.compaction_stats.compactions != before_compactions or
            (self.tombstoneReconcileDelayLocked() orelse 1) == 0 or
            self.directory_planning_slices != planning_slices_before or
            self.write_stats.manifest_writes != before_manifest_writes or
            self.obsolete_paths.count() != before_obsolete_paths or
            self.obsolete_reclaim_visits != reclaim_visits_before;
    }

    fn bulkTieredL0MaintenanceDueLocked(self: *Backend) bool {
        const fan_in = self.options.bulk_ingest_tiered_l0_fan_in;
        if (fan_in < 2) return false;
        if (!self.l0SoftPressureLocked()) return false;
        if (self.pending_bulk_plan) |pending| if (pending.retry_after_ns > self.nowNs()) return false;
        const before_sequence = self.bulk_ingest_window_first_sequence;
        // Explicit bulk sessions own a durable window and fence its runs for
        // one final linear merge. Per-request bulk transactions have no such
        // owner (sequence zero): every run in `runs` is already committed and
        // may be size-tiered while overlapping requests keep bulk mode active.
        // Refusing sequence zero disabled all proactive merging under a
        // continuous public upload and left hard-pressure compaction as the
        // only progress path.
        if (self.options.run_partition_key != null) return true;
        return compaction_mod.bulkDirectoryPlanningDue(self, .{ .fan_in = fan_in, .sequence = before_sequence, .max_bytes = self.options.max_compaction_input_bytes });
    }

    fn l0SoftPressureLocked(self: *const Backend) bool {
        return self.l0RunSoftPressureLocked() or self.l0ByteSoftPressureLocked();
    }

    fn l0RunSoftPressureLocked(self: *const Backend) bool {
        return self.effectiveL0SoftLimitRuns() > 0 and
            self.runs.l0Files() > self.effectiveL0SoftLimitRuns();
    }

    fn l0ByteSoftPressureLocked(self: *const Backend) bool {
        if (self.options.l0_soft_limit_bytes == 0) return false;
        return self.runs.l0Bytes() > self.options.l0_soft_limit_bytes;
    }

    fn l0HardPressureLocked(self: *const Backend) bool {
        return (self.effectiveL0HardLimitRuns() > 0 and self.runs.l0Files() > self.effectiveL0HardLimitRuns()) or
            (self.options.l0_hard_limit_bytes > 0 and self.runs.l0Bytes() > self.options.l0_hard_limit_bytes);
    }

    const maintenance_admission_retry_ns: u64 = 100 * std.time.ns_per_ms;

    pub fn optionalMaintenanceDeferredLocked(self: *const Backend) bool {
        return if (self.options.resource_manager) |manager|
            manager.shouldDeferSoftCompactionForDerivedReplay() or manager.shouldDeferOptionalMaintenanceForForegroundTraffic()
        else
            false;
    }

    fn bulkPlanNeededLocked(self: *const Backend, pending: *const compaction_mod.PendingBulkPlan) bool {
        return self.options.bulk_ingest_tiered_l0_fan_in >= 2 and self.l0SoftPressureLocked() and
            pending.policy.eql(.{ .fan_in = self.options.bulk_ingest_tiered_l0_fan_in, .max_bytes = self.options.max_compaction_input_bytes, .sequence = if (self.bulkIngestActive()) self.bulk_ingest_window_first_sequence else 0 });
    }

    fn retireUnneededBulkPlanLocked(self: *Backend) bool {
        if (self.bulk_plan_in_flight) return false;
        const pending = self.pending_bulk_plan orelse return false;
        if (self.bulkPlanNeededLocked(pending)) return false;
        self.pending_bulk_plan = null;
        self.retireBulkPlanning(pending);
        return true;
    }

    fn bulkPlanningWakeDelayLocked(self: *Backend) ?u64 {
        if (self.retired_bulk_plans != null) return 0;
        if (self.pending_bulk_plan) |pending| {
            if (self.bulk_plan_in_flight) return null;
            if (!self.bulkPlanNeededLocked(pending)) return 0;
            return @max(pending.retry_after_ns -| self.nowNs(), if (self.optionalMaintenanceDeferredLocked()) maintenance_admission_retry_ns else 0);
        }
        return null;
    }

    fn runWalPressureMaintenanceStepLocked(self: *Backend) !bool {
        if (!self.wal_checkpoint_pending) return false;
        const retrying_failed_checkpoint = self.wal_checkpoint_retry_reason == .checkpoint_failure;
        if (!retrying_failed_checkpoint and !self.walRetentionPressureEnabled()) return false;
        if (!self.walCheckpointRetryDueLocked()) return false;
        const before_flushes = self.write_stats.immutable_flushes;
        const before_manifest_writes = self.write_stats.manifest_writes;
        const before_wal_resets = self.write_stats.wal_resets;

        if (self.wal_pressure_blocked or retrying_failed_checkpoint) {
            // Retry the exact durable boundary after either pre-append
            // admission or post-publication cleanup failed. The recorded hard
            // pressure bit remains level-triggered; a cleanup-only failure
            // must not falsely advertise blocked write admission.
            self.checkpointCommittedStateForWalAdmissionLocked() catch |err| {
                self.write_stats.wal_pressure_failures +|= 1;
                self.scheduleWalCheckpointRetryLocked(.checkpoint_failure, true);
                return err;
            };
        } else {
            // A retry is not foreground commit latency, so soft work honors
            // the normal checkpoint cadence. Hard pressure is unconditional.
            self.enforceWalRetentionSoftPressureGuarded(true) catch |err| {
                self.write_stats.wal_pressure_failures +|= 1;
                self.scheduleWalCheckpointRetryLocked(.checkpoint_failure, true);
                return err;
            };
            self.enforceWalRetentionHardPressure(false) catch |err| {
                self.write_stats.wal_pressure_failures +|= 1;
                self.wal_pressure_blocked = true;
                self.scheduleWalCheckpointRetryLocked(.checkpoint_failure, true);
                return err;
            };
        }

        self.invalidatePrimaryWalRetentionCacheLocked();
        const retention = self.snapshotWalRetentionForPressureLocked() catch |err| {
            // Observation is part of the retry attempt: without a fresh
            // retention snapshot we cannot safely discharge pending/blocked
            // state. Advance the same capped backoff used by checkpoint I/O so
            // a persistent metadata read failure cannot hot-loop workers.
            self.write_stats.wal_pressure_failures +|= 1;
            self.scheduleWalCheckpointRetryLocked(.checkpoint_failure, true);
            return err;
        } orelse {
            self.wal_pressure_blocked = false;
            self.clearWalCheckpointRetryLocked();
            _ = self.refreshCachedMaintenanceHintLocked();
            return self.write_stats.immutable_flushes != before_flushes or
                self.write_stats.manifest_writes != before_manifest_writes or
                self.write_stats.wal_resets != before_wal_resets;
        };
        self.wal_checkpoint_pending = self.walRetentionOverSoftLimit(retention);
        self.wal_pressure_blocked = self.walRetentionOverHardLimit(retention);
        if (self.wal_checkpoint_pending) {
            self.scheduleWalCheckpointRetryLocked(if (self.wal_pressure_blocked) .hard_pressure else .soft_pressure, false);
        } else {
            self.clearWalCheckpointRetryLocked();
        }
        _ = self.refreshCachedMaintenanceHintLocked();

        return self.write_stats.immutable_flushes != before_flushes or
            self.write_stats.manifest_writes != before_manifest_writes or
            self.write_stats.wal_resets != before_wal_resets;
    }

    pub fn activeImmutableMemtableCount(self: *const Backend) usize {
        std.debug.assert(self.immutable_head <= self.immutable_memtables.items.len);
        return self.immutable_memtables.items.len - self.immutable_head;
    }

    fn activeImmutableMemtables(self: *const Backend) []const *State {
        std.debug.assert(self.immutable_head <= self.immutable_memtables.items.len);
        return self.immutable_memtables.items[self.immutable_head..];
    }

    pub fn snapshotImmutableMemtables(self: *Backend) ![]*const State {
        const active = self.activeImmutableMemtables();
        const snapshot = try self.allocator.alloc(*const State, active.len);
        errdefer self.allocator.free(snapshot);
        // Reserve for the worst case before changing any counts, making the
        // retain operation atomic with respect to allocation failure.
        try self.immutable_memtable_pins.ensureUnusedCapacity(self.allocator, active.len);
        for (active, 0..) |state, i| {
            snapshot[active.len - 1 - i] = state;
            self.retainImmutableMemtable(state);
        }
        return snapshot;
    }

    pub fn releaseImmutableMemtableSnapshot(self: *Backend, snapshot: []const *const State) void {
        self.releaseImmutableMemtablePins(snapshot);
        if (snapshot.len > 0) self.allocator.free(snapshot);
    }

    pub fn releaseImmutableMemtablePins(self: *Backend, snapshot: []const *const State) void {
        for (snapshot) |state| self.releaseImmutableMemtable(state);
        self.syncTrackedInMemoryStateUsageCurrentLocked();
    }

    fn retainImmutableMemtable(self: *Backend, state: *const State) void {
        for (self.immutable_memtable_pins.items) |*pin| {
            if (pin.state != state) continue;
            pin.readers += 1;
            return;
        }
        self.immutable_memtable_pins.appendAssumeCapacity(.{ .state = state, .readers = 1 });
    }

    fn releaseImmutableMemtable(self: *Backend, state: *const State) void {
        for (self.immutable_memtable_pins.items, 0..) |*pin, i| {
            if (pin.state != state) continue;
            std.debug.assert(pin.readers > 0);
            pin.readers -= 1;
            if (pin.readers != 0) return;
            _ = self.immutable_memtable_pins.swapRemove(i);
            self.reclaimRetiredImmutableMemtable(state);
            return;
        }
        std.debug.assert(false);
    }

    fn immutableMemtableIsPinned(self: *const Backend, state: *const State) bool {
        for (self.immutable_memtable_pins.items) |pin| {
            if (pin.state == state) return pin.readers > 0;
        }
        return false;
    }

    fn reclaimRetiredImmutableMemtable(self: *Backend, state: *const State) void {
        for (self.retired_immutable_memtables.items, 0..) |retired, i| {
            if (retired != state) continue;
            const removed = self.retired_immutable_memtables.swapRemove(i);
            self.destroyImmutableMemtable(removed);
            return;
        }
    }

    pub fn prepareReadSnapshot(self: *Backend) !void {
        if (self.mutable_read_snapshot != null) return;
        if (self.options.read_snapshot_rotate_mutable_bytes == 0) return;
        if (self.mutable.entryCount() == 0) return;
        const mutable_bytes = estimateStateBytes(&self.mutable);
        if (mutable_bytes < self.options.read_snapshot_rotate_mutable_bytes) return;

        try self.rotateMutableToImmutable();
        self.read_snapshot_mutable_rotations +|= 1;
        self.read_snapshot_mutable_rotation_bytes_total +|= mutable_bytes;
        self.read_snapshot_mutable_rotation_peak_bytes = @max(self.read_snapshot_mutable_rotation_peak_bytes, mutable_bytes);
        if (self.shouldDeferCommitFlush()) self.scheduleImmutableFlushJob();
        self.notePotentialMaintenanceDebtLocked();
    }

    pub fn prepareCurrentScanSnapshot(self: *Backend) !void {
        if (self.mutable.entryCount() == 0) return;
        const mutable_bytes = estimateStateBytes(&self.mutable);
        try self.rotateMutableToImmutable();
        self.read_snapshot_mutable_rotations +|= 1;
        self.read_snapshot_mutable_rotation_bytes_total +|= mutable_bytes;
        self.read_snapshot_mutable_rotation_peak_bytes = @max(self.read_snapshot_mutable_rotation_peak_bytes, mutable_bytes);
        if (self.shouldDeferCommitFlush()) self.scheduleImmutableFlushJob();
        self.notePotentialMaintenanceDebtLocked();
    }

    pub fn snapshotMutableState(self: *Backend) !*const State {
        return try self.snapshotMutableStateWithReason(.other);
    }

    fn cloneMutableStateWithReason(self: *Backend, reason: MutableSnapshotReason) !State {
        var snapshot = if (builtin.is_test and test_deep_mutable_snapshots)
            try self.mutable.cloneArena(self.allocator)
        else
            try self.mutable.snapshot(self.allocator);
        errdefer snapshot.deinit(self.allocator);
        snapshot.freezeMemoryAccounting();
        self.recordMutableSnapshotClone(&snapshot, reason);
        return snapshot;
    }

    fn recordMutableSnapshotClone(self: *Backend, snapshot: *const State, reason: MutableSnapshotReason) void {
        // Shared values are retained, not copied. Attribute actual index and
        // fallback owned-byte copying separately from retained-state pressure.
        var snapshot_bytes: u64 = @as(u64, @intCast(snapshot.entries.items.len)) * @sizeOf(state_mod.OwnedEntry);
        for (snapshot.entries.items) |entry| if (entry.shared == null) {
            snapshot_bytes +|= entry.key.len + entry.value.len;
            if (entry.namespace_name) |name| snapshot_bytes +|= name.len;
        };
        self.mutable_snapshot_clone_calls +|= 1;
        self.mutable_snapshot_clone_bytes_total +|= snapshot_bytes;
        self.mutable_snapshot_clone_peak_bytes = @max(self.mutable_snapshot_clone_peak_bytes, snapshot_bytes);
        const reason_index = mutableSnapshotReasonIndex(reason);
        self.mutable_snapshot_clone_by_reason[reason_index].calls +|= 1;
        self.mutable_snapshot_clone_by_reason[reason_index].bytes_total +|= snapshot_bytes;
        self.mutable_snapshot_clone_by_reason[reason_index].peak_bytes = @max(self.mutable_snapshot_clone_by_reason[reason_index].peak_bytes, snapshot_bytes);
    }

    /// Snapshot only the mutable replay-lane range needed by an async-index
    /// pass. Replay keys are append-only, so a range snapshot plus generation-
    /// pinned immutable/run state provides the same consistency as cloning the
    /// complete mutable memtable without duplicating unrelated user records.
    pub fn cloneReplayLaneMutableRange(
        self: *Backend,
        namespace: backend_types.Namespace,
        lower: []const u8,
        upper: []const u8,
    ) !State {
        // Ordered epochs are already immutable and range-seekable. Pin their
        // root in O(1); copying a replay lane would reintroduce a full mutable
        // walk and allocations under the backend lock.
        if (self.mutable.ordered_enabled) return self.cloneMutableStateWithReason(.current_scan);
        var snapshot = try self.mutable.cloneRangeArena(self.allocator, namespace, lower, upper);
        errdefer snapshot.deinit(self.allocator);
        snapshot.freezeMemoryAccounting();
        self.recordMutableSnapshotClone(&snapshot, .current_scan);
        return snapshot;
    }

    pub fn snapshotMutableStateWithReason(self: *Backend, reason: MutableSnapshotReason) !*const State {
        if (self.mutable_read_snapshot) |snapshot| {
            self.retainMutableSnapshotReader(snapshot);
            return snapshot;
        }
        if (self.mutable.entryCount() == 0) return &self.empty_mutable_snapshot;
        const snapshot = try self.allocator.create(State);
        errdefer self.allocator.destroy(snapshot);
        snapshot.* = try self.cloneMutableStateWithReason(reason);
        errdefer snapshot.deinit(self.allocator);
        try self.retired_mutable_snapshots.ensureUnusedCapacity(self.allocator, 1);
        try self.retired_mutable_snapshot_by_state.ensureUnusedCapacity(self.allocator, 1);
        try self.mutable_snapshot_reader_refs.ensureUnusedCapacity(self.allocator, 1);
        try self.mutable_snapshot_reader_ref_by_state.ensureUnusedCapacity(self.allocator, 1);
        const ref_index = self.mutable_snapshot_reader_refs.items.len;
        self.mutable_snapshot_reader_refs.appendAssumeCapacity(.{
            .state = snapshot,
            .readers = 1,
        });
        self.mutable_snapshot_reader_ref_by_state.putAssumeCapacity(snapshot, ref_index);
        self.mutable_read_snapshot = snapshot;
        self.syncTrackedInMemoryStateUsageCurrentLocked();
        return snapshot;
    }

    fn mutableSnapshotReaderRefIndex(self: *const Backend, state: *const State) ?usize {
        return self.mutable_snapshot_reader_ref_by_state.get(state);
    }

    fn removeMutableSnapshotReaderRef(self: *Backend, index: usize) MutableSnapshotReaderRef {
        const removed = self.mutable_snapshot_reader_refs.items[index];
        _ = self.mutable_snapshot_reader_ref_by_state.remove(removed.state);
        _ = self.mutable_snapshot_reader_refs.swapRemove(index);
        if (index < self.mutable_snapshot_reader_refs.items.len) {
            const moved = self.mutable_snapshot_reader_refs.items[index];
            self.mutable_snapshot_reader_ref_by_state.getPtr(moved.state).?.* = index;
        }
        return removed;
    }

    fn retainMutableSnapshotReader(self: *Backend, state: *State) void {
        const index = self.mutableSnapshotReaderRefIndex(state) orelse unreachable;
        self.mutable_snapshot_reader_refs.items[index].readers += 1;
    }

    pub fn releaseMutableReadSnapshot(self: *Backend, state: *const State) void {
        const index = self.mutableSnapshotReaderRefIndex(state) orelse {
            std.debug.assert(state == &self.empty_mutable_snapshot);
            return;
        };
        const ref = &self.mutable_snapshot_reader_refs.items[index];
        std.debug.assert(ref.readers > 0);
        ref.readers -= 1;
        if (ref.readers != 0 or self.mutable_read_snapshot == state) return;

        const remove_index = self.retired_mutable_snapshot_by_state.get(state) orelse unreachable;
        self.removeRetiredMutableSnapshot(remove_index);
        const owned = self.removeMutableSnapshotReaderRef(index).state;
        self.destroyMutableSnapshot(owned);
        self.syncTrackedInMemoryStateUsageCurrentLocked();
    }

    pub fn cloneCurrentScanMutableStateForBulkIngest(self: *Backend) !?State {
        if (!self.bulkIngestActive()) return null;
        if (self.options.bulk_ingest_current_scan_clone_max_bytes == 0) return null;
        if (self.mutable.entryCount() == 0) return State{ .frozen_memory_bytes = 0 };
        const mutable_bytes = estimateStateBytes(&self.mutable);
        if (mutable_bytes > self.options.bulk_ingest_current_scan_clone_max_bytes) return null;
        if (!self.canAdmitBulkIngestCurrentScanClone(mutable_bytes)) {
            self.bulk_ingest_current_scan_clone_budget_denials +|= 1;
            return null;
        }
        var snapshot = self.cloneMutableStateWithReason(.bulk_current_scan) catch |err| switch (err) {
            error.OutOfMemory => {
                self.bulk_ingest_current_scan_clone_oom_fallbacks +|= 1;
                return null;
            },
        };
        errdefer snapshot.deinit(self.allocator);
        const snapshot_bytes = estimateStateBytes(&snapshot);
        if (!self.canAdmitBulkIngestCurrentScanClone(snapshot_bytes)) {
            self.bulk_ingest_current_scan_clone_budget_denials +|= 1;
            snapshot.deinit(self.allocator);
            return null;
        }
        if (snapshot.account) |account| {
            const refs = try self.bulk_snapshot_accounts.getOrPut(self.allocator, account);
            if (!refs.found_existing) refs.value_ptr.* = 0;
            refs.value_ptr.* += 1;
        } else self.bulk_snapshot_unshared_bytes +|= snapshot_bytes;
        self.bulk_ingest_current_scan_clone_active_bytes +|= snapshot_bytes;
        self.bulk_ingest_current_scan_clone_peak_active_bytes = @max(
            self.bulk_ingest_current_scan_clone_peak_active_bytes,
            self.bulk_ingest_current_scan_clone_active_bytes,
        );
        self.syncTrackedInMemoryStateUsageCurrentLocked();
        return snapshot;
    }

    fn canAdmitBulkIngestCurrentScanClone(self: *const Backend, bytes: u64) bool {
        const total_max = self.options.bulk_ingest_current_scan_clone_total_max_bytes;
        if (total_max == 0) return true;
        if (bytes > total_max) return false;
        return self.bulk_ingest_current_scan_clone_active_bytes <= total_max - bytes;
    }

    pub fn releaseCurrentScanMutableStateForBulkIngest(self: *Backend, snapshot: *const State) void {
        const snapshot_bytes = estimateStateBytes(snapshot);
        if (snapshot.account) |account| {
            const refs = self.bulk_snapshot_accounts.getPtr(account).?;
            refs.* -= 1;
            if (refs.* == 0) _ = self.bulk_snapshot_accounts.remove(account);
        } else self.bulk_snapshot_unshared_bytes -|= snapshot_bytes;
        if (snapshot_bytes >= self.bulk_ingest_current_scan_clone_active_bytes) {
            self.bulk_ingest_current_scan_clone_active_bytes = 0;
        } else {
            self.bulk_ingest_current_scan_clone_active_bytes -= snapshot_bytes;
        }
        self.syncTrackedInMemoryStateUsageCurrentLocked();
    }

    pub fn invalidateMutableReadSnapshot(self: *Backend) void {
        const snapshot = self.mutable_read_snapshot orelse return;
        self.mutable_read_snapshot = null;
        self.retireMutableSnapshot(snapshot);
        self.syncTrackedInMemoryStateUsageCurrentLocked();
    }

    fn destroyImmutableMemtable(self: *Backend, state: *State) void {
        self.destroyMutableSnapshot(state);
    }

    fn destroyMutableSnapshot(self: *Backend, state: *State) void {
        @import("lsm_backend/memtable_reclamation.zig").retire(self, state);
    }

    /// Owned replay/bulk snapshots use the same infallible handoff as shared
    /// reader epochs. Caller holds Backend.mu and transfers the header.
    pub fn retireOwnedMutableSnapshot(self: *Backend, state: *State) void {
        self.destroyMutableSnapshot(state);
    }

    /// Detach retired generations while serialized; reclaim their potentially
    /// large subtrees outside the writer lock. A lifecycle pin protects close.
    pub fn unlockWithReclamation(self: *Backend) void {
        @import("lsm_backend/ledger_reclamation.zig").reclaimSliceLocked(self);
        @import("lsm_backend/memtable_reclamation.zig").reclaimSliceLocked(self);
        if ((self.outputCleanupDelayLocked() orelse 1) == 0) self.cached_maintenance_hint.store(1, .release);
        // Reclamation releases lifecycle pins only. It must not initiate a
        // best-effort manifest write and consume a durability error belonging
        // to the explicit sync/publication operation that unlocked us.
        self.reclaimClosurePlanningSliceLocked();
        self.reclaimGcPlanningSliceLocked();
        self.reclaimBulkPlanningSliceLocked();
        self.reclaimStoreSliceLocked();
        @import("lsm_backend/read_metadata_reclamation.zig").reclaimSliceLocked(self);
        self.reclaimDirectorySliceLocked();
        var turns: usize = 0;
        while (self.retired_read_versions != null and turns < 8) : (turns += 1) {
            var batch = ReclaimingMemory{ .next = self.reclaiming_memory, .versions = self.retired_read_versions };
            self.retired_read_versions = null;
            var version = batch.versions;
            while (version) |item| : (version = item.retired_next) {
                if (item.directory) |dir| dir.retainAccounting();
            }
            self.reclaiming_memory = &batch;
            self.retainReaderKind(.other);
            self.mu.unlock();
            version = batch.versions;
            while (version) |item| : (version = item.retired_next) item.destroyContents(self);
            _ = runtime_mod.lockBackend(Backend, self);
            var link = &self.reclaiming_memory;
            while (link.*.? != &batch) link = &link.*.?.next;
            link.* = batch.next;
            version = batch.versions;
            while (version) |item| {
                version = item.retired_next;
                if (item.directory) |dir| {
                    dir.releaseAccounting();
                    item.allocator.destroy(dir);
                }
                item.allocator.destroy(item);
            }
            // File pins held by retired metadata have now been released. Run
            // the usual reader-release checkpoint only after reclamation.
            self.obsolete_reclaim_retry_at_ns = 0;
            self.releaseReaderKind(.other);
            self.syncTrackedInMemoryStateUsageCurrentLocked();
        }
        if ((self.outputCleanupDelayLocked() orelse 1) == 0) self.cached_maintenance_hint.store(1, .release);
        // Small snapshot retirements normally finish in this unlock. Only
        // residual debt warrants a worker; pre-unlock scheduling would submit
        // an otherwise empty background job on each ordinary manifest edit.
        if ((self.retired_ledger_snapshots != null and !self.ledger_reclaim_in_flight) or
            @import("lsm_backend/memtable_reclamation.zig").pending(self) or
            @import("lsm_backend/read_metadata_reclamation.zig").pending(self) or
            (!self.directory_reclaim_in_flight and (self.directory_reclaimer != null or self.retired_run_directories != null))) self.scheduleMaintenanceJobLocked(true);
        self.mu.unlock();
    }

    fn reclaimDirectorySliceLocked(self: *Backend) void {
        if (self.directory_reclaim_in_flight) return;
        if (self.directory_reclaimer == null and self.retired_run_directories == null) return;
        self.directory_reclaim_in_flight = true;
        defer self.directory_reclaim_in_flight = false;
        var credits: usize = 2048;
        const deadline = runtime_mod.workNowNs(self) +| 2 * std.time.ns_per_ms;
        while (credits != 0 and runtime_mod.workNowNs(self) < deadline) {
            if (self.directory_reclaimer == null) {
                const directory = self.retired_run_directories orelse break;
                self.retired_run_directories = directory.retired_next;
                self.directory_reclaimer = .init(directory);
            }
            self.retainReaderKind(.other);
            self.mu.unlock();
            var quantum: usize = @min(credits, 64);
            const before = quantum;
            const done = self.directory_reclaimer.?.step(self.allocator, &quantum);
            _ = runtime_mod.lockBackend(Backend, self);
            credits -= before - quantum;
            if (done) {
                self.directory_reclaimer.?.finish(self.allocator);
                self.directory_reclaimer = null;
            }
            self.releaseReaderKind(.other);
        }
        self.syncTrackedInMemoryStateUsageCurrentLocked();
    }

    pub fn retireRunStore(self: *Backend, store: *RunStore) void {
        store.retired_next = self.retired_run_stores;
        self.retired_run_stores = store;
    }

    fn reclaimStoreSliceLocked(self: *Backend) void {
        if (self.store_reclaim_in_flight) return;
        if (self.store_reclaimer == null and self.retired_run_stores == null) return;
        self.store_reclaim_in_flight = true;
        defer self.store_reclaim_in_flight = false;
        var credits: usize = 2048;
        const deadline = runtime_mod.workNowNs(self) +| 2 * std.time.ns_per_ms;
        while (credits != 0 and runtime_mod.workNowNs(self) < deadline) {
            if (self.store_reclaimer == null) {
                const store = self.retired_run_stores orelse break;
                self.retired_run_stores = store.retired_next;
                self.store_reclaimer = .init(store);
            }
            self.retainReaderKind(.other);
            self.mu.unlock();
            var quantum: usize = @min(credits, 64);
            const before = quantum;
            const done = self.store_reclaimer.?.step(self.allocator, &quantum);
            _ = runtime_mod.lockBackend(Backend, self);
            credits -= before - quantum;
            if (done) {
                self.store_reclaimer.?.finish(self.allocator);
                self.store_reclaimer = null;
            }
            self.releaseReaderKind(.other);
        }
        self.syncTrackedInMemoryStateUsageCurrentLocked();
    }

    pub fn retireClosurePlanning(self: *Backend, pending: *compaction_mod.PendingDirectoryClosure) void {
        pending.retired_next = self.retired_closures;
        self.retired_closures = pending;
    }

    pub fn retireAdmission(self: *Backend, pending: *compaction_mod.PendingAdmission) void {
        pending.retired_next = self.retired_admissions;
        self.retired_admissions = pending;
    }

    fn reclaimAdmissionSliceLocked(self: *Backend) void {
        if (self.admission_reclaim_in_flight) return;
        const pending = self.retired_admissions orelse return;
        self.admission_reclaim_in_flight = true;
        self.retainReaderKind(.other);
        self.mu.unlock();
        var credits: usize = 2048;
        var done = false;
        const deadline = runtime_mod.workNowNs(self) +| 2 * std.time.ns_per_ms;
        while (credits != 0 and runtime_mod.workNowNs(self) < deadline) {
            var quantum: usize = @min(credits, 64);
            const before = quantum;
            done = pending.cleanupStep(self.allocator, &quantum);
            credits -= before - quantum;
            if (done) break;
        }
        _ = runtime_mod.lockBackend(Backend, self);
        if (done) {
            var link = &self.retired_admissions;
            while (link.*.? != pending) link = &link.*.?.retired_next;
            link.* = pending.retired_next;
            pending.destroy(self);
        }
        self.admission_reclaim_in_flight = false;
        self.releaseReaderKind(.other);
    }

    pub fn retireBulkPlanning(self: *Backend, pending: *compaction_mod.PendingBulkPlan) void {
        self.unregisterBulkPlanning(pending);
        pending.retired_next = self.retired_bulk_plans;
        self.retired_bulk_plans = pending;
    }
    pub fn unregisterBulkPlanning(self: *Backend, pending: *compaction_mod.PendingBulkPlan) void {
        var link = &self.active_bulk_plans;
        while (link.*) |active| {
            if (active == pending) {
                link.* = active.active_next;
                active.active_next = null;
                return;
            }
            link = &active.active_next;
        }
    }
    fn reclaimBulkPlanningSliceLocked(self: *Backend) void {
        if (self.bulk_plan_reclaim_in_flight) return;
        const pending = self.retired_bulk_plans orelse return;
        self.bulk_plan_reclaim_in_flight = true;
        defer self.bulk_plan_reclaim_in_flight = false;
        self.retainReaderKind(.other);
        self.mu.unlock();
        var credits: usize = 2048;
        var done = false;
        const deadline = runtime_mod.workNowNs(self) +| 2 * std.time.ns_per_ms;
        while (credits != 0 and runtime_mod.workNowNs(self) < deadline) {
            var quantum: usize = @min(credits, 64);
            const before = quantum;
            done = pending.cleanupStep(self.allocator, &quantum);
            credits -= before - quantum;
            if (done) break;
        }
        _ = runtime_mod.lockBackend(Backend, self);
        if (done) {
            var link = &self.retired_bulk_plans;
            while (link.*.? != pending) link = &link.*.?.retired_next;
            link.* = pending.retired_next;
            pending.finish(self);
        }
        self.releaseReaderKind(.other);
    }

    fn reclaimClosurePlanningSliceLocked(self: *Backend) void {
        self.reclaimAdmissionSliceLocked();
        if (self.closure_reclaim_in_flight) return;
        const pending = self.retired_closures orelse return;
        self.closure_reclaim_in_flight = true;
        self.retainReaderKind(.other);
        self.mu.unlock();
        var credits: usize = 2048;
        var done = false;
        const deadline = runtime_mod.workNowNs(self) +| 2 * std.time.ns_per_ms;
        while (credits != 0 and runtime_mod.workNowNs(self) < deadline) {
            var quantum: usize = @min(credits, 64);
            const before = quantum;
            done = pending.cleanupStep(self.allocator, &quantum);
            credits -= before - quantum;
            if (done) break;
        }
        _ = runtime_mod.lockBackend(Backend, self);
        if (done) {
            var link = &self.retired_closures;
            while (link.*.? != pending) link = &link.*.?.retired_next;
            link.* = pending.retired_next;
            pending.destroy(self);
        }
        self.closure_reclaim_in_flight = false;
        self.releaseReaderKind(.other);
    }

    pub fn retireGcPlanning(self: *Backend, pending: *compaction_mod.PendingGc) void {
        pending.discardIntent(self);
        pending.retired_next = self.retired_gc;
        self.retired_gc = pending;
    }

    fn reclaimGcPlanningSliceLocked(self: *Backend) void {
        if (self.gc_reclaim_in_flight) return;
        const pending = self.retired_gc orelse return;
        self.gc_reclaim_in_flight = true;
        self.retainReaderKind(.other);
        self.mu.unlock();
        var credits: usize = 2048;
        var done = false;
        const deadline = runtime_mod.workNowNs(self) +| 2 * std.time.ns_per_ms;
        while (credits != 0 and runtime_mod.workNowNs(self) < deadline) {
            var quantum: usize = @min(credits, 64);
            const before = quantum;
            done = pending.cleanupStep(self.allocator, &quantum);
            credits -= before - quantum;
            if (done) break;
        }
        _ = runtime_mod.lockBackend(Backend, self);
        if (done) {
            var link = &self.retired_gc;
            while (link.*.? != pending) link = &link.*.?.retired_next;
            link.* = pending.retired_next;
            pending.destroy(self);
        }
        self.gc_reclaim_in_flight = false;
        self.releaseReaderKind(.other);
    }

    fn reserveImmutableMemtableRetirement(self: *Backend, state: *const State) !void {
        if (!self.immutableMemtableIsPinned(state)) return;
        try self.retired_immutable_memtables.ensureUnusedCapacity(self.allocator, 1);
    }

    fn retireImmutableMemtable(self: *Backend, state: *State) void {
        if (!self.immutableMemtableIsPinned(state)) {
            self.destroyImmutableMemtable(state);
            return;
        }
        // Publication reserves this slot before the replacement runs become
        // visible. The ownership transition after publication must not fail:
        // readers may still hold pointers into this immutable generation.
        self.retired_immutable_memtables.appendAssumeCapacity(state);
        self.syncTrackedInMemoryStateUsageCurrentLocked();
    }

    fn retireMutableSnapshot(self: *Backend, state: *State) void {
        const ref_index = self.mutableSnapshotReaderRefIndex(state) orelse unreachable;
        if (self.mutable_snapshot_reader_refs.items[ref_index].readers == 0) {
            _ = self.removeMutableSnapshotReaderRef(ref_index);
            self.destroyMutableSnapshot(state);
            return;
        }
        // Capacity is reserved when the snapshot is published, before any
        // reader can observe it. Retirement therefore cannot fail while a
        // reader still owns the generation.
        const retired_index = self.retired_mutable_snapshots.items.len;
        self.retired_mutable_snapshots.appendAssumeCapacity(state);
        self.retired_mutable_snapshot_by_state.putAssumeCapacity(state, retired_index);
    }

    fn removeRetiredMutableSnapshot(self: *Backend, index: usize) void {
        const removed = self.retired_mutable_snapshots.items[index];
        _ = self.retired_mutable_snapshot_by_state.remove(removed);
        _ = self.retired_mutable_snapshots.swapRemove(index);
        if (index < self.retired_mutable_snapshots.items.len) {
            const moved = self.retired_mutable_snapshots.items[index];
            self.retired_mutable_snapshot_by_state.getPtr(moved).?.* = index;
        }
    }

    fn drainRetiredImmutableMemtables(self: *Backend) void {
        var i: usize = 0;
        while (i < self.retired_immutable_memtables.items.len) {
            const state = self.retired_immutable_memtables.items[i];
            if (self.immutableMemtableIsPinned(state)) {
                i += 1;
                continue;
            }
            _ = self.retired_immutable_memtables.swapRemove(i);
            self.destroyImmutableMemtable(state);
        }
        self.syncTrackedInMemoryStateUsageCurrentLocked();
    }

    fn drainRetiredMutableSnapshots(self: *Backend) void {
        for (self.retired_mutable_snapshots.items) |state| {
            if (self.mutableSnapshotReaderRefIndex(state)) |index| {
                std.debug.assert(self.mutable_snapshot_reader_refs.items[index].readers == 0);
                _ = self.removeMutableSnapshotReaderRef(index);
            }
            self.destroyMutableSnapshot(state);
        }
        self.retired_mutable_snapshots.clearRetainingCapacity();
        self.retired_mutable_snapshot_by_state.clearRetainingCapacity();
        self.syncTrackedInMemoryStateUsageCurrentLocked();
    }

    fn compactImmutableMemtableQueue(self: *Backend) void {
        if (self.immutable_head == 0) return;
        const active_count = self.activeImmutableMemtableCount();
        if (active_count > 0) {
            std.mem.copyForwards(*State, self.immutable_memtables.items[0..active_count], self.immutable_memtables.items[self.immutable_head..]);
            std.mem.copyForwards(WalSegmentRange, self.immutable_wal_ranges.items[0..active_count], self.immutable_wal_ranges.items[self.immutable_head..]);
        }
        self.immutable_memtables.items.len = active_count;
        self.immutable_wal_ranges.items.len = active_count;
        self.immutable_head = 0;
    }

    fn noteMutableWalSegment(self: *Backend, segment: u64) void {
        if (segment == 0) return;
        if (!self.mutable_wal_range.isSet()) {
            self.mutable_wal_range = .{ .first = segment, .last = segment };
            return;
        }
        self.mutable_wal_range.first = @min(self.mutable_wal_range.first, segment);
        self.mutable_wal_range.last = @max(self.mutable_wal_range.last, segment);
    }

    fn oldestActiveWalSegment(self: *const Backend) ?u64 {
        var oldest: ?u64 = if (self.mutable_wal_range.isSet()) self.mutable_wal_range.first else null;
        for (self.immutable_wal_ranges.items[self.immutable_head..]) |range| {
            if (!range.isSet()) continue;
            oldest = if (oldest) |current| @min(current, range.first) else range.first;
        }
        return oldest;
    }

    fn maybeCheckpointWalAfterManifestPublish(self: *Backend) !void {
        if (self.manifest_recovery_required) return error.RecoveryRequired;
        if (!self.options.wal_enabled or self.root_dir == null or self.options.backend.read_only) return;
        if (self.recovery_replaying_wal) return;
        // A newer flush can finish while an older manifest is syncing. Empty
        // memtables alone no longer prove that the WAL is covered durably.
        if (!self.manifestCoversCurrentRuns()) return;
        if (self.mutable.entryCount() == 0 and self.activeImmutableMemtableCount() == 0) {
            try self.resetWalAfterManifestCheckpoint();
            return;
        }
        const oldest_active = self.oldestActiveWalSegment() orelse return;
        if (oldest_active <= 1) return;
        var wal_lock = try self.acquireWalOperationLock(.exclusive);
        defer wal_lock.release();
        try self.wal_retention.retireCoveredSegments(
            self.storage.?,
            self.allocator,
            self.root_dir.?,
            oldest_active - 1,
        );
        self.syncTrackedWalRetentionUsageCurrentLocked();
    }

    fn estimateStateBytes(state: anytype) u64 {
        if (comptime @hasDecl(@TypeOf(state.*), "estimatedMemoryBytes")) return state.estimatedMemoryBytes();
        var total: u64 = @as(u64, @intCast(state.entries.capacity)) * @sizeOf(state_mod.OwnedEntry);
        if (state.arena_owner) |arena| {
            // Arena frees are intentionally deferred until the whole memtable
            // is released. Query its actual capacity so hot overwrites and
            // allocator growth slack participate in flush/admission limits.
            total +|= arena.queryCapacity();
        } else {
            for (state.entries.items) |entry| {
                total +|= entry.sharedOverheadBytes();
                if (entry.namespace_name) |name| total += name.len;
                total += entry.key.len;
                total += entry.value.len;
            }
        }
        if (comptime @hasDecl(@TypeOf(state.*), "estimatedIndexMemoryBytes")) {
            total +|= state.estimatedIndexMemoryBytes();
        }
        return total;
    }

    fn estimateStateLogicalBytes(state: anytype) u64 {
        if (comptime @hasDecl(@TypeOf(state.*), "estimatedLogicalBytes")) {
            return state.estimatedLogicalBytes();
        }
        var total: u64 = 0;
        for (state.entries.items) |entry| {
            if (entry.namespace_name) |name| total += name.len;
            total += entry.key.len;
            total += entry.value.len;
            total += @sizeOf(state_mod.OwnedEntry);
        }
        return total;
    }

    fn stateMeetsByteFlushThreshold(state: anytype, logical_threshold: u64) bool {
        if (logical_threshold == 0) return false;
        if (estimateStateLogicalBytes(state) >= logical_threshold) return true;
        const memory_threshold = std.math.mul(
            u64,
            logical_threshold,
            mutable_memory_guard_multiplier,
        ) catch std.math.maxInt(u64);
        return estimateStateBytes(state) >= memory_threshold;
    }

    fn estimatedFlushIoBytes(state: *const State) u64 {
        const bytes = estimateStateLogicalBytes(state);
        return bytes +| bytes;
    }

    fn noteImmutablePublishedForWal(self: *Backend, state: *const State) void {
        // Run construction already walks every entry, so computing this once
        // at publication does not change flush complexity. Commits thereafter
        // consume only the maintained aggregate.
        const logical_bytes = estimateStateLogicalBytes(state);
        std.debug.assert(logical_bytes <= self.active_immutable_logical_bytes);
        self.active_immutable_logical_bytes -|= logical_bytes;
        self.unpublished_wal_logical_bytes +|= logical_bytes;
        self.unpublished_wal_max_batch_logical_bytes = @max(
            self.unpublished_wal_max_batch_logical_bytes,
            logical_bytes,
        );
    }

    fn maintenanceLevelRunTarget(level: u32, base: usize, multiplier: usize) usize {
        if (level == 0) return 0;
        var target = @max(@as(usize, 1), base);
        var remaining = level - 1;
        while (remaining > 0) : (remaining -= 1) {
            target = std.math.mul(usize, target, @max(@as(usize, 1), multiplier)) catch return std.math.maxInt(usize);
        }
        return target;
    }

    pub fn capabilities(_: *Backend) backend_types.Capabilities {
        return .{
            .ordered_ranges = true,
            .reverse_ranges = true,
            .cursors = true,
            .ordered_append_puts = true,
            .unordered_bulk_append_puts = true,
            .native_namespaces = false,
            .write_batches = .atomic,
            .single_writer = true,
            .read_snapshots = .snapshot,
        };
    }

