    fn recordTableCompressionWriteStats(self: *Backend, stats: lsm_table_file.CompressionStats) void {
        self.write_stats.table_file_logical_entry_bytes +|= stats.logical_entry_bytes;
        self.write_stats.table_file_physical_entry_bytes +|= stats.physical_entry_bytes;
        self.write_stats.table_file_raw_blocks +|= stats.raw_blocks;
        self.write_stats.table_file_compressed_blocks +|= stats.compressed_blocks;
        self.write_stats.table_file_compression_codec_mask |= stats.compression_codec_mask;
    }

    pub fn resolveRunState(self: *Backend, run: *Run) !*const State {
        return try self.resolveRunStateWithAllocator(run, self.allocator);
    }

    fn resolveRunStateWithAllocator(self: *Backend, run: *Run, allocator: Allocator) !*const State {
        if (self.storage != null) {
            if (run.path) |path| {
                if (run.cached_state_index) |index| {
                    if (!self.cachedRunStateIndexMatches(index, path, run.id)) {
                        run.cached_state_index = null;
                    }
                }
                if (run.cached_state_index == null) {
                    run.cached_state_index = try self.getCachedRunStateIndex(path, run.id);
                }
                return self.getCachedRunStateByIndex(run.cached_state_index.?);
            }
        }
        if (self.storage) |storage| return try run.ensureStateWithStorage(allocator, storage);
        return try run.ensureState(allocator);
    }

    pub fn cachedRunStateIndexMatches(self: *const Backend, index: usize, path: []const u8, run_id: u64) bool {
        return index < self.run_state_cache.items.len and
            self.run_state_cache.items[index].run_id == run_id and
            std.mem.eql(u8, self.run_state_cache.items[index].path, path);
    }

    pub fn registerOpenManifestRunRefs(self: *Backend) !void {
        var cursor = self.runs.cursor();
        while (cursor.next()) |record| {
            const run = record.versionOwner();
            if (run.version_ref_pinned) continue;
            const path = run.path orelse continue;
            try obsolete_path_refs.retain(path);
            run.version_ref_pinned = true;
        }
    }

    pub fn invalidateReadVersion(self: *Backend) void {
        self.run_directory_dirty = true;
        self.run_directory_generation +%= 1;
        if (self.domain_index) |index| {
            index.retired_next = null;
            if (self.retired_domain_indexes_tail) |tail| tail.retired_next = index else self.retired_domain_indexes = index;
            self.retired_domain_indexes_tail = index;
        }
        self.domain_index = null;
        const version = self.read_version orelse return;
        self.read_version = null;
        version.release(self);
    }

    pub fn retireReadVersion(self: *Backend, version: *runtime_mod.ReadVersion) void {
        if (version.registered) {
            if (version.live_previous) |previous| previous.live_next = version.live_next else {
                std.debug.assert(self.live_read_versions == version);
                self.live_read_versions = version.live_next;
            }
            if (version.live_next) |next| next.live_previous = version.live_previous;
            version.live_next = null;
            version.live_previous = null;
            version.registered = false;
        }
        if (version.directory != null) {
            version.retired_next = null;
            if (self.retired_projection_versions_tail) |tail| tail.retired_next = version else self.retired_projection_versions = version;
            self.retired_projection_versions_tail = version;
            return;
        }
        version.retired_next = self.retired_read_versions;
        self.retired_read_versions = version;
    }

    pub fn destroyRunMetadata(self: *Backend) void {
        @import("lsm_backend/read_metadata_reclamation.zig").drainJoined(self);
        if (self.pending_tombstone_reconcile) |pending| pending.destroy(self);
        self.pending_tombstone_reconcile = null;
        if (self.pending_bulk_plan) |pending| pending.destroy(self);
        self.pending_bulk_plan = null;
        while (self.retired_bulk_plans) |pending| {
            self.retired_bulk_plans = pending.retired_next;
            pending.destroy(self);
        }
        if (self.pending_gc) |pending| pending.destroy(self);
        self.pending_gc = null;
        while (self.retired_gc) |pending| {
            self.retired_gc = pending.retired_next;
            pending.destroy(self);
        }
        if (self.directory_reclaimer) |*job| {
            var credits: usize = std.math.maxInt(usize);
            std.debug.assert(job.step(self.allocator, &credits));
            job.finish(self.allocator);
            self.directory_reclaimer = null;
        }
        if (self.pending_directory_closure) |pending| pending.destroy(self);
        for (&self.pending_admissions) |*slot| {
            if (slot.*) |pending| pending.destroy(self);
            slot.* = null;
        }
        while (self.retired_admissions) |pending| {
            self.retired_admissions = pending.retired_next;
            pending.destroy(self);
        }
        self.pending_directory_closure = null;
        if (self.pending_l0_directory_closure) |pending| pending.destroy(self);
        self.pending_l0_directory_closure = null;
        while (self.retired_closures) |pending| {
            self.retired_closures = pending.retired_next;
            pending.destroy(self);
        }
        // Cancelling an unfinished GC intent retires prepared writer roots.
        // Drain stores AFTER job destruction, otherwise close leaks every
        // payload still owned by those newly retired candidate versions.
        if (self.store_reclaimer) |*job| {
            var credits: usize = std.math.maxInt(usize);
            std.debug.assert(job.step(self.allocator, &credits));
            job.finish(self.allocator);
            self.store_reclaimer = null;
        }
        while (self.retired_run_stores) |store| {
            self.retired_run_stores = store.retired_next;
            store.deinit(self.allocator);
            self.allocator.destroy(store);
        }
        self.manifest_journal.deinit(self.allocator);
        if (self.manifest_directory) |directory| directory.destroy(self.allocator);
        self.manifest_directory = null;
        if (self.run_directory) |directory| directory.destroy(self.allocator);
        self.run_directory = null;
        while (self.retired_run_directories) |directory| {
            self.retired_run_directories = directory.retired_next;
            directory.destroy(self.allocator);
        }
        while (self.retired_read_versions) |version| {
            self.retired_read_versions = version.retired_next;
            version.destroy(self);
        }
    }

    fn retireRunDirectory(self: *Backend, directory: *RunDirectory) void {
        directory.retired_next = self.retired_run_directories;
        self.retired_run_directories = directory;
    }

    pub fn retireCheckpointDirectory(self: *Backend, directory: *RunDirectory) void {
        self.retireRunDirectory(directory);
    }

    pub fn publishManifestDirectory(self: *Backend, prepared: ?*RunDirectory) void {
        if (self.manifest_directory) |old| self.retireRunDirectory(old);
        self.manifest_directory = prepared;
    }

    pub fn prepareRunDirectoryChange(self: *Backend, removed: ?compaction_mod.CompactionPlan, added: []const Run) !?*RunDirectory {
        // Seed on the first SST publication even if the table has never been
        // read. Otherwise write-only ingestion would defer a full rebuild to
        // its first reader. Empty stores themselves need no directory charge.
        if (self.run_directory_dirty and self.runs.count() != 0) try self.ensureRunDirectory();
        const prepared = if (self.runs.count() == 0)
            try RunDirectory.create(self.allocator)
        else if (self.run_directory) |directory|
            try directory.fork(self.allocator)
        else
            return null;
        errdefer prepared.destroy(self.allocator);
        if (removed) |plan| {
            for (0..plan.source_len + plan.target_len) |i| try prepared.remove(self.allocator, run_store_mod.planAt(self, plan, i));
        }
        for (added) |run| try prepared.put(self, run);
        return prepared;
    }

    pub fn prepareRunDirectoryMove(self: *Backend, source: *const Run, level: u32) !?*RunDirectory {
        if (self.run_directory_dirty) try self.ensureRunDirectory();
        const directory = self.run_directory orelse return null;
        const prepared = try directory.fork(self.allocator);
        errdefer prepared.destroy(self.allocator);
        var run = source.*;
        try prepared.remove(self.allocator, &run);
        run.level = level;
        try prepared.put(self, run);
        return prepared;
    }

    pub fn publishRunDirectory(self: *Backend, prepared: ?*RunDirectory) void {
        const directory = prepared orelse return;
        if (self.run_directory) |old| self.retireRunDirectory(old);
        self.run_directory = directory;
        self.run_directory_dirty = false;
    }

    /// Cold initialization/full administrative rewrites rebuild once. Normal
    /// flushes, compactions and level moves publish only their metadata delta.
    fn ensureRunDirectory(self: *Backend) !void {
        if (!self.run_directory_dirty) if (self.run_directory) |directory| {
            if (directory.count() == self.runs.count()) return;
        };
        const directory = try RunDirectory.create(self.allocator);
        errdefer directory.destroy(self.allocator);
        var cursor = self.runs.cursor();
        while (cursor.next()) |run| try directory.put(self, run.*);
        self.publishRunDirectory(directory);
    }

    pub fn createReadVersionFromDirectory(self: *Backend) !*runtime_mod.ReadVersion {
        if (self.read_version) |version| return version;
        try self.ensureRunDirectory();
        const directory = try self.run_directory.?.fork(self.allocator);
        errdefer directory.destroy(self.allocator);
        const version = try self.allocator.create(runtime_mod.ReadVersion);
        version.* = .{ .allocator = self.allocator, .directory = directory, .prepared = false, .registered = true, .live_next = self.live_read_versions };
        if (self.live_read_versions) |head| head.live_previous = version;
        self.live_read_versions = version;
        self.read_version = version;
        self.syncTrackedInMemoryStateUsageCurrentLocked();
        return version;
    }

    /// Caller owns an epoch reference and holds the backend mutex. The exact
    /// pinned epoch is prepared once, even if publication advances meanwhile.
    pub fn prepareReadVersion(self: *Backend, version: *runtime_mod.ReadVersion) !void {
        return self.prepareReadVersionControlled(version, null);
    }

    pub fn prepareReadVersionWithAdmission(self: *Backend, version: *runtime_mod.ReadVersion, control: read_admission.Port) !void {
        return self.prepareReadVersionControlled(version, control);
    }

    /// Returns with the backend mutex held on every outcome. Rejection uses
    /// mandatory physical reentry before releasing epoch/accounting ownership.
    fn reacquireReadPreparationBackend(self: *Backend, control: ?read_admission.Port) !void {
        if (control) |owner| {
            _ = runtime_mod.lockBackendWithAdmission(Backend, self, owner) catch |err| {
                _ = runtime_mod.lockBackend(Backend, self);
                return err;
            };
        } else _ = runtime_mod.lockBackend(Backend, self);
    }

    fn prepareReadVersionControlled(self: *Backend, version: *runtime_mod.ReadVersion, control: ?read_admission.Port) !void {
        if (control) |owner| try owner.checkLifetime();
        if (version.prepared) return;
        self.retainReaderKind(.other);
        defer self.releaseReaderKind(.other);
        var owns_build = false;
        defer if (owns_build) {
            std.debug.assert(version.preparing);
            version.preparing = false;
        };
        while (true) {
            if (control) |owner| try owner.checkLifetime();
            if (version.prepared) return;
            if (!version.preparing) {
                version.preparing = true;
                owns_build = true;
                break;
            }
            const owner = control orelse break;
            // A coarse wait may retain the very CPU slot the producer needs.
            // Only coalesce callers that can lend execution while suspended.
            if (!try owner.hasExecutionWait()) break;
            // Coalesce admitted peers, but never block a legacy caller on a
            // producer that may need its CPU slot. Legacy callers may build a
            // separately reserved candidate and race publication instead.
            runtime_mod.unlockBackend(Backend, self, true);
            const waited = owner.waitForProgress();
            const reentry = self.reacquireReadPreparationBackend(control);
            try reentry;
            try waited;
        }
        const directory = version.directory.?;
        const build_started = self.readStatsNowNs();
        runtime_mod.unlockBackend(Backend, self, true);
        var reservation: ?resource_manager_mod.Reservation = null;
        const built: anyerror!*runtime_mod.ReadVersion = blk: {
            if (control) |owner| owner.checkpoint() catch |err| break :blk err;
            if (self.options.resource_manager) |manager| {
                reservation = manager.reserve(.lsm_in_memory_state, runtime_mod.ReadVersion.buildMemoryBound(directory.count())) catch |err| break :blk @as(anyerror!*runtime_mod.ReadVersion, err);
            }
            break :blk runtime_mod.ReadVersion.createFromDirectoryWithAdmission(self.allocator, directory, control);
        };
        defer if (reservation) |*lease| lease.release();
        var transferred = false;
        defer if (!transferred) {
            if (built) |projection| projection.discardProjection() else |_| {}
        };
        const final_reentry = self.reacquireReadPreparationBackend(control);
        try final_reentry;
        const projection = try built;
        if (control) |owner| try owner.checkLifetime();
        // A legacy candidate may have won while this producer was suspended.
        // Discard our arrays without releasing the epoch's directory ownership.
        if (version.prepared) return;
        // Transfer only the projection. The epoch already owns this root.
        version.runs = projection.runs;
        version.l0_groups = projection.l0_groups;
        version.levels = projection.levels;
        version.projection_bytes = projection.projection_bytes;
        transferred = true;
        self.allocator.destroy(projection);
        version.prepared = true;
        self.read_version_builds +|= 1;
        self.recordRunGroupBuild(version.runs.len, if (version.levels.len != 0) version.levels[0].start_index else version.runs.len, self.readStatsElapsedNs(build_started));
        self.syncTrackedInMemoryStateUsageCurrentLocked();
    }

    pub fn mountRunDirectory(self: *Backend) !void {
        if (self.runs.count() == 0 and self.manifest_backing == null and self.recovered_manifest == null) return;
        try self.ensureRunDirectory();
        try self.manifest_journal.recoverState(self);
        self.syncTrackedInMemoryStateUsageCurrentLocked();
    }

    pub fn domainIndex(self: *Backend) !*const compaction_mod.DomainIndex {
        if (self.domain_index) |index| return index;
        // Small indexes are already single-flight under the backend mutex.
        if (self.runs.count() <= 64) {
            var reservation: ?resource_manager_mod.Reservation = null;
            defer if (reservation) |*lease| lease.release();
            if (self.options.resource_manager) |manager| reservation = try manager.reserve(.lsm_in_memory_state, compaction_mod.DomainIndex.buildMemoryBound(self.runs.count()));
            self.domain_index = try compaction_mod.DomainIndex.create(self);
            self.domain_index_builds +|= 1;
            self.syncTrackedInMemoryStateUsageCurrentLocked();
            return self.domain_index.?;
        }
        self.retainReaderKind(.compaction);
        runtime_mod.unlockBackend(Backend, self, true);
        const build_io: ?std.Io = if (comptime builtin.os.tag == .freestanding) null else if (self.options.read_runtime) |read_runtime| read_runtime.io else null;
        if (build_io) |io| self.domain_index_build_mu.lockUncancelable(io) else platform.sync.lockYielding(&self.domain_index_build_fallback_mu);
        _ = runtime_mod.lockBackend(Backend, self);
        defer self.releaseReaderKind(.compaction);
        defer if (build_io) |io| self.domain_index_build_mu.unlock(io) else self.domain_index_build_fallback_mu.unlock();
        if (self.domain_index == null) {
            var reservation: ?resource_manager_mod.Reservation = null;
            defer if (reservation) |*lease| lease.release();
            if (self.runs.count() <= 64) {
                if (self.options.resource_manager) |manager| reservation = try manager.reserve(.lsm_in_memory_state, compaction_mod.DomainIndex.buildMemoryBound(self.runs.count()));
                self.domain_index = try compaction_mod.DomainIndex.create(self);
            } else {
                if (self.read_version == null) {
                    self.read_version = try runtime_mod.ReadVersion.create(self);
                }
                const version = self.read_version.?;
                _ = version.references.fetchAdd(1, .monotonic);
                defer version.release(self);
                try self.prepareReadVersion(version);
                if (self.read_version != version) return error.CompactionPlanningStale;
                if (self.options.resource_manager) |manager| reservation = try manager.reserve(.lsm_in_memory_state, compaction_mod.DomainIndex.buildMemoryBound(version.runs.len));
                self.retainReaderKind(.compaction);
                var snapshot = .{ .allocator = self.allocator, .options = self.options, .planning_directory = version.directory, .runs = std.ArrayListUnmanaged(Run){ .items = version.runs, .capacity = 0, .pointer_stability = .{} } };
                runtime_mod.unlockBackend(Backend, self, true);
                const built = compaction_mod.DomainIndex.create(&snapshot);
                _ = runtime_mod.lockBackend(Backend, self);
                defer self.releaseReaderKind(.compaction);
                const index = try built;
                if (self.domain_index) |current| {
                    index.destroy(self.allocator);
                    return current;
                }
                if (self.read_version != version) {
                    index.destroy(self.allocator);
                    return error.CompactionPlanningStale;
                }
                // Rebind borrowed metadata to the live version before releasing
                // the temporary pin. Publication invalidates this cache first.
                for (index.order, 0..) |run_index, i| index.runs[i] = self.runs.at(run_index).*;
                self.domain_index = index;
            }
            self.domain_index_builds +|= 1;
            self.syncTrackedInMemoryStateUsageCurrentLocked();
        }
        return self.domain_index.?;
    }

    pub fn planningDirectory(self: *Backend) !*const RunDirectory {
        try self.ensureRunDirectory();
        return self.run_directory.?;
    }

    /// Directory payloads keep this stable pin capability until their final
    /// release. No backend pointer or borrowed map slot escapes registration.
    pub fn retainDirectoryRunSnapshotPin(_: *Backend, run: *Run) !RunDirectory.EntryPin {
        if (run.version_ref_pinned) return error.InvalidArgument;
        const path = run.path orelse return .{ .owner = &run_snapshot_refs, .release = releaseDirectorySnapshotPin };
        while (true) {
            var registration = prepareRunSnapshotRefOperation(path, .retain);
            defer registration.deinit();
            _ = registration.planWithAdmission(null) catch |cause| {
                if (cause == error.CompactionPlanningStale) continue;
                return cause;
            };
            try registration.resumeWithAdmission(null);
            registration.publishWithAdmission(null) catch |cause| {
                if (cause == error.CompactionPlanningStale) continue;
                return cause;
            };
            return completeDirectorySnapshotPin(&registration, run, null);
        }
    }
    /// Caller prepays the operation header and planned additional allocation,
    /// pins input, and registers physical retirement before running this cursor.
    pub fn prepareRunSnapshotRefOperation(path: []const u8, mode: run_pin_registry.Mode) run_pin_registry.Operation {
        return .init(&run_snapshot_refs, path, mode);
    }
    pub const DirectoryEntryPreparation = RunDirectory.EntryPreparation(Backend);
    /// Register/prepay the frame and pin immutable source before resuming it.
    /// Allocator/domain authority and the source outlive their owned work. The
    /// frame captures capabilities; no backend pointer survives this call.
    /// Transferred file pins retain their independent global issuer lifetime.
    pub fn beginDirectoryEntryPreparation(self: *Backend, directory: *RunDirectory, source: Run, owner: *PinQuota.Owner, original: read_admission.Port) !DirectoryEntryPreparation {
        return DirectoryEntryPreparation.init(directory, self, source, owner, original);
    }

    pub const PublicationResources = @import("lsm_backend/publication_resources.zig").Owner;
    /// Stable controller resources acquire the actual process host before
    /// registration; no caller-supplied no-op host or backend borrow escapes.
    pub fn beginPublicationResourcesWithAdmission(self: *Backend, original: read_admission.Port) !*PublicationResources {
        return PublicationResources.start(self.allocator, self.options.resource_manager orelse return error.ExecutionWaitUnsupported, original);
    }

    pub const DirectoryEntryOwner = @import("lsm_backend/directory_entry_owner.zig").Owner;
    pub const DirectoryEntryLifetime = @import("lsm_backend/directory_entry_owner.zig").Lifetime;
    pub const DirectoryEntryHostLifetime = @import("lsm_backend/directory_entry_owner.zig").HostLifetime;

    /// Register the resident observer and final anchor before a prepared entry
    /// escapes into candidate/live roots. Source/ancestor ownership transfers
    /// only on success; normal cleanup never borrows this backend receiver.
    pub fn ownPreparedDirectoryEntry(preparation: *DirectoryEntryPreparation, host: *?DirectoryEntryHostLifetime, lifetime: *?DirectoryEntryLifetime, original: read_admission.Port) !*DirectoryEntryOwner {
        return DirectoryEntryOwner.create(preparation, host, lifetime, releaseDirectorySnapshotPin, directorySnapshotPinRetirement(), original);
    }

    /// Prepay/register construction, resident accounting and the final anchor
    /// before variable work. Lifetime's in/out value records whether source
    /// authority transferred, including constructor refusal after registration.
    pub fn beginOwnedDirectoryEntryPreparation(self: *Backend, directory: *RunDirectory, source: Run, owner: *PinQuota.Owner, host: *?DirectoryEntryHostLifetime, lifetime: *?DirectoryEntryLifetime, original: read_admission.Port) !*DirectoryEntryOwner {
        return DirectoryEntryOwner.start(self, directory, source, owner, host, lifetime, directorySnapshotPinRetirement(), original);
    }
    pub fn beginOwnedDirectoryEntryFromRegisteredSource(self: *Backend, directory: *RunDirectory, source: *const RunDirectory.EntryLease, owner: *PinQuota.Owner, host: *?DirectoryEntryHostLifetime, original: read_admission.Port) !*DirectoryEntryOwner {
        return DirectoryEntryOwner.startFromRegisteredSource(self, directory, source, owner, host, directorySnapshotPinRetirement(), original);
    }

    pub fn unregisteredDirectorySnapshotPin() RunDirectory.EntryPin {
        return .{ .owner = &run_snapshot_refs, .release = releaseDirectorySnapshotPin };
    }
    fn completeDirectorySnapshotPin(registration: *run_pin_registry.Operation, run: *Run, original: ?@import("../common/read_admission.zig").Port) !RunDirectory.EntryPin {
        if (original) |port| try port.checkpoint();
        if (registration.registry != &run_snapshot_refs or registration.mode != .retain) return error.InvalidArgument;
        if (run.version_ref_pinned) return error.InvalidArgument;
        const path = run.path orelse return error.CompactionPlanningStale;
        if (path.ptr != registration.path.ptr or path.len != registration.path.len) return error.CompactionPlanningStale;
        const pin = try registration.takePinWithAdmission(null);
        // The checked original cannot reject between taking the owned file
        // pin and marking its immutable run. No allocation or callback here.
        run.version_ref_pinned = true;
        return .{ .owner = pin, .release = releaseDirectorySnapshotPin };
    }
    pub fn completeDirectorySnapshotPinWithAdmission(registration: *run_pin_registry.Operation, run: *Run, original: @import("../common/read_admission.zig").Port) !RunDirectory.EntryPin {
        return completeDirectorySnapshotPin(registration, run, original);
    }
    fn releaseDirectorySnapshotPin(owner: *anyopaque, run: *Run) void {
        if (!run.version_ref_pinned) return;
        const pin: *RunSnapshotRefRegistry.Pin = @ptrCast(@alignCast(owner));
        pin.release();
        run.version_ref_pinned = false;
    }
    /// Fail closed before interpreting a foreign/legacy opaque pin owner.
    pub fn beginDirectorySnapshotRetirement(lease: *RunDirectory.EntryLease, original: @import("../common/read_admission.zig").Port) !RunDirectory.EntryLease.Retirement {
        return lease.beginRetirementForPinWithAdmission(releaseDirectorySnapshotPin, directorySnapshotPinRetirement(), original);
    }
    /// Only for directory EntryPins issued above. The context is global and
    /// release never dereferences a backend, hashes a path, allocates or locks.
    fn directorySnapshotPinRetirement() RunDirectory.EntryLease.PinRelease {
        return .{ .context = &run_snapshot_refs, .resume_fn = struct {
            fn call(_: *anyopaque, owner: *anyopaque, run: *Run, original: ?@import("../common/read_admission.zig").Port) !void {
                if (original) |port| try port.checkpoint();
                releaseDirectorySnapshotPin(owner, run);
            }
        }.call };
    }

    pub fn retainRunSnapshotRef(_: *Backend, run: *Run) !void {
        const path = run.path orelse return;
        try run_snapshot_refs.retain(path);
        run.version_ref_pinned = true;
    }

    pub fn releaseRunSnapshotRef(_: *Backend, run: *Run) void {
        releaseDirectoryRunSnapshotRef(run);
    }

    pub fn releaseDirectoryRunSnapshotRef(run: *Run) void {
        if (!run.version_ref_pinned) return;
        if (run.path) |path| run_snapshot_refs.release(path);
        run.version_ref_pinned = false;
    }

    pub fn forgetRunSnapshotRef(_: *Backend, run: *Run) void {
        if (run.path) |path| run_snapshot_refs.forget(path);
    }

    pub fn releaseRunVersionRef(self: *Backend, run: *Run) void {
        _ = self;
        const owned = run.versionOwner();
        if (!owned.version_ref_pinned) return;
        if (owned.path) |path| obsolete_path_refs.release(path);
        owned.version_ref_pinned = false;
    }

    fn destroyOwnedRun(run: *Run, allocator: Allocator) void {
        if (run.version_ref_pinned) if (run.path) |path| obsolete_path_refs.release(path);
        if (run.path) |path| run_snapshot_refs.forget(path);
        run.deinit(allocator);
    }

    fn obsoletePathPinnedByOpenVersion(self: *Backend, path: []const u8) bool {
        if (self.manifest_journal.protectsPath(path)) return true;
        if (repository_mod.manifest_set.identify(path)) |file| {
            if (self.manifest_checkpoint_build_id == file.id) return true;
        }
        return obsolete_path_refs.isRetained(path) or run_snapshot_refs.isRetained(path);
    }

