            try std.testing.expect(lane.submitted_job == null);
            try std.testing.expect(!backend.immutable_flush_job_in_flight);

            {
                var txn = try backend.beginWrite();
                try txn.put(.{}, "key:a", "new");
                try txn.put(.{}, "key:b", "visible");
