        test "lsm backend write pressure compacts hard L0 debt" {
            var backend = Backend.init(std.testing.allocator, .{
                .flush_threshold = 1,
                .compact_threshold_runs = 100,
                .l0_soft_limit_runs = 1,
                .l0_hard_limit_runs = 2,
            });
            defer backend.close();

            var i: usize = 0;
            while (i < 3) : (i += 1) {
                var key_buf: [16]u8 = undefined;
