                    const self: *@This() = @ptrCast(@alignCast(ptr));
                    if (self.run_path) |run_path| {
                        if (std.mem.eql(u8, path, run_path)) self.run_file_size_reads += 1;
                    }
                    return self.backing.storage().fileSize(path);
                }

