                    const self: *@This() = @ptrCast(@alignCast(ptr));
                    return self.backing.storage().syncFileContentsAbsolute(path);
                }

                fn syncParentAbsolute(ptr: *anyopaque, path: []const u8) !void {
                    const self: *@This() = @ptrCast(@alignCast(ptr));
                    return self.backing.storage().syncParentAbsolute(path);
                }

