            var runtime = try backend.runtimeStore(alloc, .{ .name = "docs" });
            defer runtime.deinit();

            {
                var txn = try runtime.beginWrite();
                try txn.put("doc:a", "A");
                try txn.commit();
            }

            var old_reader = try runtime.beginRead();
