            for (0..32) |_| {
                if (!try backend.runMaintenanceStep()) break;
            }
            try std.testing.expect(!run_snapshot_refs.isRetained(first_run_path));
            if (backing.storage().readFileAlloc(alloc, first_run_path, 1024)) |unexpected| {
